const TS=32, COLS=25, ROWS=15;
const GRAVITY=0.8, JUMP_VY=-14.0, SPRING_VY=-30.0, MOVE_SPEED=4.0, MAX_FALL=12;
const EMPTY=0,GROUND=1,BRICK=2,SPIKE=3,SPRING=4,COIN=5,TROPHY=6;
const TILEMAP=[
".........................",
".........................",
"......C..................",
"......BBB................",
"....................BBBBT",
"........................T",
"...........C.........BBB.",
"...........BBB...........",
"............BBB..........",
".........................",
"........BBB..............",
".....CCC.................",
".........................",
"###S##P#######S##########",
"#########################"];
const L={'.':0,'#':1,'B':2,'S':3,'P':4,'C':5,'T':6};
let grid=[];
for(let r=0;r<ROWS;r++){let row=[];for(let c=0;c<COLS;c++)row.push(L[TILEMAP[r][c]]??0);grid.push(row);}
function isSolid(t){return t===GROUND||t===BRICK||t===SPRING;}
function tileAt(px,py){let tx=Math.floor(px/TS),ty=Math.floor(py/TS);if(tx<0||tx>=COLS||ty<0||ty>=ROWS)return EMPTY;return grid[ty][tx];}
function hCol(p){
  let left=Math.floor(p.x/TS),right=Math.floor((p.x+p.w-1)/TS),top=Math.floor(p.y/TS),bottom=Math.floor((p.y+p.h-1)/TS);
  for(let ty=top;ty<=bottom;ty++){
    let tr=tileAt(right*TS,ty*TS),tl=tileAt(left*TS,ty*TS);
    if(p.vx>0&&isSolid(tr)){p.x=right*TS-p.w-0.01;p.vx=0;}
    else if(p.vx<0&&isSolid(tl)){p.x=(left+1)*TS+0.01;p.vx=0;}
  }
}
function vCol(p){
  let left=Math.floor(p.x/TS),right=Math.floor((p.x+p.w-1)/TS),top=Math.floor(p.y/TS),bottom=Math.floor((p.y+p.h-1)/TS);
  let spring=false;
  for(let tx=left;tx<=right;tx++){
    let tt=tileAt(tx*TS,top*TS),tb=tileAt(tx*TS,bottom*TS);
    if(p.vy>0&&isSolid(tb)){p.y=bottom*TS-p.h-0.01;p.vy=0;p.onGround=true;if(tb===SPRING)spring=true;}
    else if(p.vy<0&&isSolid(tt)){p.y=(top+1)*TS+0.01;p.vy=0;}
  }
  if(spring){p.vy=SPRING_VY;p.onGround=false;}
}
// A "stand node": player bottom rests on solid tile (sx,sy), player occupies cell above.
function simJump(sx,sy,vx){
  let p={x:sx*TS,y:sy*TS-32,w:32,h:32,vx:0,vy:0,onGround:true};
  p.vy=JUMP_VY; p.vx=vx; p.onGround=false;
  const lands=new Set(); const pickups=new Set();
  let t=0;
  while(t<200){
    p.vy+=GRAVITY; if(p.vy>MAX_FALL)p.vy=MAX_FALL;
    p.x+=p.vx; hCol(p);
    p.y+=p.vy; vCol(p);
    // pickups touched
    let l=Math.floor(p.x/TS),r=Math.floor((p.x+p.w-1)/TS),tp=Math.floor(p.y/TS),bt=Math.floor((p.y+p.h-1)/TS);
    for(let ty=tp;ty<=bt;ty++)for(let tx=l;tx<=r;tx++){
      let t2=grid[ty][tx];
      if(t2===COIN)pickups.add(tx+','+ty);
      if(t2===TROPHY)pickups.add('T:'+tx+','+ty);
    }
    if(p.onGround){
      let btx=Math.floor((p.x+p.w/2)/TS);
      let by=Math.floor((p.y+p.h-0.5)/TS);
      lands.add(btx+','+by);
      break;
    }
    t++;
  }
  return {lands,pickups};
}
// build graph
const standNodes=new Set();
for(let r=0;r<ROWS;r++)for(let c=0;c<COLS;c++){
  if(isSolid(grid[r][c]) && r>0 && !isSolid(grid[r-1][c])) standNodes.add(c+','+r);
}
const adj={};
for(const n of standNodes){
  const [sx,sy]=n.split(',').map(Number);
  adj[n]=new Set();
  for(const vx of [-4,0,4]){
    const res=simJump(sx,sy,vx);
    for(const l of res.lands) adj[n].add(l);
  }
}
// BFS from start (player starts standing on ground tile col1 row13 -> node '1,13')
const start='1,13';
const visited=new Set(); const q=[start]; visited.add(start);
while(q.length){const cur=q.shift(); for(const nb of (adj[cur]||[])){if(!visited.has(nb)){visited.add(nb);q.push(nb);}}}
console.log('Reachable stand nodes:', visited.size, '/', standNodes.size);
// Which coins/trophy reachable: collect coins along reachable stands and pickups
const coinTiles=[];for(let r=0;r<ROWS;r++)for(let c=0;c<COLS;c++)if(grid[r][c]===COIN)coinTiles.push(c+','+r);
console.log('Coin tiles:', coinTiles);
// For each reachable stand node, which coins can be picked from standing there
let canCollect={};
for(const n of coinTiles) canCollect[n]=false;
for(const n of visited){
  const [sx,sy]=n.split(',').map(Number);
  for(const vx of [-4,0,4]){const res=simJump(sx,sy,vx);for(const pk of res.pickups){if(coinTiles.includes(pk))canCollect[pk]=true;}}
}
console.log('Coins collectable from reachable stands:', JSON.stringify(canCollect));
console.log('Trophy reachable (stand adjacency to trophy)?', '---');
EOF
