// ---- Builder ----
function Map(w,h){
  const g=Array.from({length:h},()=>Array(w).fill('.'));
  return {
    w,h,g,
    solid:(y,x0,x1)=>{for(let x=x0;x<=x1;x++)g[y][x]='#';},
    brick:(x,y,w0)=>{for(let i=0;i<w0;i++)g[y][x+i]='B';},
    // ladder column from topRow..bottomRow inclusive (see rules)
    ladder:(x,topRow,bottomRow)=>{for(let r=topRow;r<=bottomRow;r++)g[r][x]='|';},
    spike:(x,y)=>{g[y][x]='S';},
    spring:(x,y)=>{g[y][x]='P';},
    coin:(x,y)=>{g[y][x]='C';},
    heart:(x,y)=>{g[y][x]='H';},
    star:(x,y)=>{g[y][x]='*';},
    trophy:(x,y)=>{g[y][x]='T';},
    rows:()=>g.map(r=>r.join('')),
  };
