const {Map,L1}=require('/var/folders/ny/fflj10fx21j0l321qz4htkxm0000gp/T/opencode/gen_ladder.js');
const TS=32;
const GRAVITY=0.8, JUMP_VY=-14.0, SPRING_VY=-25.0, MOVE_SPEED=4.0, MAX_FALL=12;
const E=0,GROUND=1,BRICK=2,SPIKE=3,SPRING=4,COIN=5,TROPHY=6,HEART=7,STAR=8,LADDER=9;
const LEGEND={'.':0,'#':1,'B':2,'S':3,'P':4,'C':5,'T':6,'H':7,'*':8,'|':9};

function validate(name, map){
  const ROWS=map.length, COLS=map[0].length;
  let grid=[];for(let r=0;r<ROWS;r++){let row=[];for(let c=0;c<COLS;c++)row.push(LEGEND[map[r][c]]??0);grid.push(row);}
  function isSolid(t){return t===GROUND||t===BRICK||t===SPRING;}
  function tileAt(px,py){let tx=Math.floor(px/TS),ty=Math.floor(py/TS);if(tx<0||tx>=COLS||ty<0||ty>=ROWS)return E;return grid[ty][tx];}
  function hCol(p){let l=Math.floor(p.x/TS),r=Math.floor((p.x+p.w-1)/TS),t=Math.floor(p.y/TS),b=Math.floor((p.y+p.h-1)/TS);
    for(let ty=t;ty<=b;ty++){let tr=tileAt(r*TS,ty*TS),tl=tileAt(l*TS,ty*TS);
      if(p.vx>0&&isSolid(tr)){p.x=r*TS-p.w-0.01;p.vx=0;}else if(p.vx<0&&isSolid(tl)){p.x=(l+1)*TS+0.01;p.vx=0;}}}
  function vCol(p,useSpring){let l=Math.floor(p.x/TS),r=Math.floor((p.x+p.w-1)/TS),t=Math.floor(p.y/TS),b=Math.floor((p.y+p.h-1)/TS);
    let spring=false;
    for(let tx=l;tx<=r;tx++){let tt=tileAt(tx*TS,t*TS),tb=tileAt(tx*TS,b*TS);
      if(p.vy>0&&isSolid(tb)){p.y=b*TS-p.h-0.01;p.vy=0;p.onGround=true;if(tb===SPRING)spring=true;}
      else if(p.vy<0&&isSolid(tt)){p.y=(t+1)*TS+0.01;p.vy=0;}}
    if(spring&&useSpring){p.vy=SPRING_VY;p.onGround=false;}}
  // jump/fall sim from a foot cell (fx,fy): feet in row fy, player bottom = fy*TS+? 
  // Treat start bottom at fy*TS (feet row fy). Player y such that bottom = fy*TS+TS? Use bottom=fy*TS.
  function sim(fx,fy,vy0,policy){
    let p={x:fx*TS,y:(fy)*TS-32,w:32,h:32,vx:0,vy:vy0,onGround:false};
    let f=0;const lands=new Set();
    while(f<400){p.vx=policy[Math.min(f,policy.length-1)];
      p.vy+=GRAVITY;if(p.vy>MAX_FALL)p.vy=MAX_FALL;p.x+=p.vx;hCol(p);p.y+=p.vy;vCol(p,true);
      if(p.onGround){let by=Math.floor((p.y+p.h+0.99)/TS);let bx=Math.floor((p.x+p.w/2)/TS);if(by<ROWS)lands.add(bx+','+by);break;}
      f++;}
    return lands;}
  const pol=[];const dirs=[-1,0,1];for(const d of dirs)for(const N of [0,4,8,12,16,20,24,28,32,36,40]){let a=[];for(let i=0;i<N;i++)a.push(d*MOVE_SPEED);a.push(0);pol.push(a);}
  for(const A of [-1,1])for(const B of [-1,0,1])for(const N of [8,16,24]){let a=[];for(let i=0;i<N;i++)a.push(A*MOVE_SPEED);for(let i=0;i<40;i++)a.push(B*MOVE_SPEED);pol.push(a);}
  // foot-cell reachability
  const surface=ROWS-2; // player starts on surface row
  const R=new Set();
  const startKey=1+','+surface; R.add(startKey);
  // ladder runs per column
  function ladderRun(x,row){ // contiguous ladder rows containing 'row'
    if(grid[row][x]!==LADDER) return null;
    let top=row; while(top-1>=0 && grid[top-1][x]===LADDER) top--;
    let bot=row; while(bot+1<ROWS && grid[bot+1][x]===LADDER) bot++;
    return {top,bot};
  }
