    changed=false;
    const keys=[...R];
    for(const key of keys){
      const [fx,fy]=key.split(',').map(Number);
      // 1) jump/fall (if standing on solid)
      if(isSolid(grid[fy][fx])){
        for(const pp of pol){
          const j=sim(fx,fy,-14,pp); for(const L of j){if(!R.has(L)){R.add(L);changed=true;}}
          const w=sim(fx,fy,0,pp);   for(const L of w){if(!R.has(L)){R.add(L);changed=true;}}
        }
      }
