    for(let ty=t;ty<=b;ty++){let tr=tileAt(r*TS,ty*TS),tl=tileAt(l*TS,ty*TS);
      if(p.vx>0&&isSolid(tr)){p.x=r*TS-p.w-0.01;p.vx=0;}else if(p.vx<0&&isSolid(tl)){p.x=(l+1)*TS+0.01;p.vx=0;}}}
  function vCol(p,useSpring){let l=Math.floor(p.x/TS),r=Math.floor((p.x+p.w-1)/TS),t=Math.floor(p.y/TS),b=Math.floor((p.y+p.h-1)/TS);
    let spring=false;
    for(let tx=l;tx<=r;tx++){let tt=tileAt(tx*TS,t*TS),tb=tileAt(tx*TS,b*TS);
      if(p.vy>0&&isSolid(tb)){p.y=b*TS-p.h-0.01;p.vy=0;p.onGround=true;if(tb===SPRING)spring=true;}
