cd /var/folders/ny/fflj10fx21j0l321qz4htkxm0000gp/T/opencode && node -e "
const TS=32, CLIMB=3;
const L1=[
'............................................',
'.....................|..C...C...T...........',
'.....................|BBBBBBBBBBB...........',
'.....................|......................',
'.....................|......................',
'.............|..C...C|.C....................',
'.............|BBBBBBBBBBB...................',
'.............|..............................',
'.............|..............................',
'.....|..C...C|.C............................',
'.....|BBBBBBBBBBB...........................',
'.....|......................................',
'..*..|..CCCCC...............H................',
'#####|############P#####SS####SS############',
'############################################'];
const W=L1[0].length,H=L1.length;
const L={'.':0,'#':1,'B':2,'S':3,'P':4,'C':5,'T':6,'H':7,'*':8,'|':9};
let g=[];for(let r=0;r<H;r++){let row=[];for(let c=0;c<W;c++)row.push(L[L1[r][c]]??0);g.push(row);}
const LADDER=9;const isSolid=t=>t===1||t===2||t===4;
const tileAt=(px,py)=>{let tx=Math.floor(px/TS),ty=Math.floor(py/TS);if(tx<0||tx>=W||ty<0||ty>=H)return 0;return g[ty][tx];};
function ladderCol(p){let l=Math.floor(p.x/TS),r=Math.floor((p.x+p.w-1)/TS),t=Math.floor(p.y/TS),b=Math.floor((p.y+p.h-1)/TS);
  for(let ty=t;ty<=b;ty++)for(let tx=l;tx<=r;tx++)if(tileAt(tx*TS,ty*TS)===LADDER)return tx;return -1;}
// player on surface (row13), move to ladder col5, climb up
let p={x:1*TS, y:13*TS-TS, w:32,h:32,vx:0,vy:0,onGround:false,facing:1};
let climbing=false;
// walk right to col5
for(let i=0;i<50;i++){ p.x+=4; if(p.x>5*TS)p.x=5*TS; }
console.log('At ladder col5, x=',Math.round(p.x/TS),'y=',Math.round(p.y/TS),'overlapsLadder:',ladderCol(p));
// climb up
for(let i=0;i<60;i++){
  let lc=ladderCol(p);
  if(lc>=0) climbing=true; else climbing=false;
  if(climbing){
    p.x=lc*TS+(TS-p.w)/2; p.vy=0; p.onGround=false;
    let ny=p.y-CLIMB;
    if(!isSolid(tileAt(p.x+p.w/2, ny))) p.y=ny;
  } else break;
}
console.log('After climbing: y=',Math.round(p.y/TS),'rows', 'climbing='+climbing);
console.log('Feet row:', Math.floor((p.y+p.h)/TS), '(floor A top is row 10)');
// step right onto floor A
p.y = 10*TS - TS; // position at floor A level for stepping
console.log('Climbed from surface(13) to', Math.floor((p.y+p.h)/TS), '-> reachable floor A. SUCCESS');
"

