const fs=require('fs');
let code=fs.readFileSync('gloop-escape.html','utf8').match(/<script>([\s\S]*?)<\/script>/)[1];
const hook='window.__g={get boss(){return boss;},get player(){return player;},get state(){return state;},get projectiles(){return projectiles;},loadLevel:loadLevel};';
code=code.replace(/\}\)\(\);\s*$/, hook+'\n})();');
function grad(){return {addColorStop:()=>{}};}
const ctxStub=new Proxy({}, {get:(t,p)=>{ if(p==='createLinearGradient')return grad; return ()=>({}); }, set:()=>true});
const canvasStub={getContext:()=>ctxStub};
const listeners={};
global.document={getElementById:()=>canvasStub};
let raf=null; global.requestAnimationFrame=(fn)=>{raf=fn;};
const wnd={addEventListener:(ev,fn)=>{listeners[ev]=fn;}};
global.window=wnd;
new Function('document','requestAnimationFrame','window', code)(global.document, global.requestAnimationFrame, wnd);
const g=wnd.__g;
let t=0; const step=(n)=>{for(let i=0;i<n;i++){t+=16.66; raf&&raf(t);}};
// boot L1 then boss
g.loadLevel(4); step(30);
console.log('Boss level loaded, hp=',g.boss.hp);
for(let i=0;i<120;i++) step(1);
console.log('Fired projectiles:', g.projectiles.length>0, 'count now:', g.projectiles.length);
// stomp test
let before=g.boss.hp;
for(let k=0;k<20 && g.boss.alive;k++){
  g.player.x=g.boss.x+g.boss.w/2-16;
  g.player.y=g.boss.y-33; g.player.vy=5; g.player.onGround=false;
  step(8);
}
console.log('hp before='+before+' after='+(g.boss?g.boss.hp:'dead')+' state='+g.state);
console.log('BOSS TEST COMPLETE');
"

