const {Map}=require('/var/folders/ny/fflj10fx21j0l321qz4htkxm0000gp/T/opencode/gen_ladder.js');
// Safe building helpers -------------------------------------------------
// A staircase of floors rising to the right, each connected by a ladder at
// the left edge of the upper floor (floors overlap so ladders are adjacent).
function staircase(W,H,floors,floorLen,opts){
  // floors: array of rows (ascending index = higher). e.g. [10,6,2]
  const surface=H-2;
  const m=Map(W,H);
  m.solid(surface,0,W-1); m.solid(H-1,0,W-1);
  let x0=4;
  const x=[];
  floors.forEach((r,i)=>{ x[i]=x0+i*(floorLen-3); m.brick(x[i],r,floorLen); });
  // ladders between consecutive floors
  for(let i=1;i<floors.length;i++){
    const lx=x[i]-1; // left edge of upper floor, inside lower floor
    m.ladder(lx, floors[i]-1, floors[i-1]-1);
  }
  // surface->first floor ladder
  m.ladder(x[0]-1, floors[0]-1, surface-1);
  // trophy at top floor right end
  const top=floors[floors.length-1];
  m.trophy(x[floors.length-1]+floorLen-2, top-1);
  // coins on floors + surface
  floors.forEach((r,i)=>{
    for(let c=x[i]+2;c<x[i]+floorLen-1;c+=3) m.coin(c,r-1);
  });
  for(let c=6;c<W-6;c+=4){ if(m.g[12][c]==='.') m.coin(c,12); }
  // props from opts
