const { staircase, tower, zigzag, islands, pitgauntlet } = require('./gen_many.js');
const { validate } = require('./validate_mod.js');
const { Map } = require('./gen_ladder.js');

// ---- 16 normal levels mixing 5 archetypes (adjacent levels differ) ----
const normal = [
  ['stair', staircase(44, 15, [10, 6, 2], 11, { spikes: [20, 24], heart: 26, double: 20, speed: 28 })],
  ['islands', islands(60, 17, [{ x: 6, y: 13, w: 6 }, { x: 14, y: 10, w: 6 }, { x: 22, y: 7, w: 6 }, { x: 30, y: 4, w: 6 }, { x: 38, y: 1, w: 6 }], { spikes: [46, 50], heart: 24, double: 12 })],
  ['zigzag', zigzag(56, 17, [11, 7, 3], 11, { spikes: [20, 32], heart: 26, double: 22 })],
  ['pit', pitgauntlet(64, 15, [[8, 9], [18, 19], [28, 29], [38, 39], [48, 49]], { spikes: [14, 24, 44], heart: 28, star: 40, double: 12 })],
  // World 2
  ['tower', tower(52, 18, 4, { spikes: [20, 34], heart: 26, double: 22 })],
  ['pit', pitgauntlet(72, 16, [[10, 11], [22, 23], [34, 35], [46, 47], [58, 59]], { spikes: [16, 28, 40, 52], double: 16, speed: 50 })],
  ['islands', islands(68, 18, [{ x: 6, y: 14, w: 6 }, { x: 14, y: 11, w: 6 }, { x: 22, y: 8, w: 6 }, { x: 30, y: 5, w: 6 }, { x: 38, y: 2, w: 6 }], { spikes: [50, 54], star: 46, double: 14, speed: 20 })],
  ['stair', staircase(60, 17, [12, 8, 4], 11, { spikes: [20, 24, 40, 44], springs: [28], heart: 30, double: 14, speed: 36 })],
  // World 3
  ['zigzag', zigzag(64, 18, [12, 8, 4], 11, { spikes: [22, 40], star: 30, double: 28 })],
  ['islands', islands(72, 19, [{ x: 6, y: 15, w: 6 }, { x: 14, y: 12, w: 6 }, { x: 22, y: 9, w: 6 }, { x: 30, y: 6, w: 6 }, { x: 38, y: 3, w: 6 }], { spikes: [56, 60], star: 46, double: 18, speed: 24 })],
  ['pit', pitgauntlet(80, 17, [[12, 13], [26, 27], [40, 41], [54, 55], [68, 69]], { spikes: [18, 32, 46, 60], double: 20, speed: 56, star: 50 })],
  ['tower', tower(60, 19, 5, { spikes: [24, 40], star: 30, double: 26, speed: 44 })],
  // World 4
  ['stair', staircase(70, 18, [12, 8, 4], 12, { spikes: [22, 38, 52], springs: [30], heart: 26, double: 16, speed: 46 })],
  ['pit', pitgauntlet(84, 18, [[12, 13], [28, 29], [44, 45], [60, 61], [76, 77]], { spikes: [20, 36, 52, 68], double: 22, speed: 58, star: 48, heart: 32 })],
  ['islands', islands(72, 20, [{ x: 6, y: 16, w: 6 }, { x: 14, y: 13, w: 6 }, { x: 22, y: 10, w: 6 }, { x: 30, y: 7, w: 6 }, { x: 38, y: 4, w: 6 }], { spikes: [58, 62], star: 48, double: 20, speed: 26 })],
  ['zigzag', zigzag(76, 19, [14, 10, 6, 2], 11, { spikes: [24, 40, 56, 66], springs: [32], star: 50, double: 26, speed: 52 })],
];

// ---- boss arena ----
function makeBossArena(W) {
  const H = 16, surface = 14, m = Map(W, H);
  m.solid(surface, 0, W - 1); m.solid(H - 1, 0, W - 1);
  m.brick(10, 8, 8); m.brick(W - 18, 8, 8); m.brick(Math.floor(W / 2) - 4, 5, 8);
  m.ladder(9, 7, 13); m.ladder(Math.floor(W / 2) - 5, 4, 8); m.ladder(W - 19, 7, 13);
  m.heart(Math.floor(W / 2), 12); m.star(Math.floor(W / 2), 4);
  m.coin(12, 7); m.coin(W - 14, 7); m.coin(Math.floor(W / 2) - 2, 4); m.coin(Math.floor(W / 2) + 2, 4);
  return m.rows();
}
const bossMaps = [makeBossArena(48), makeBossArena(56), makeBossArena(64), makeBossArena(72)];

// ---- themes ----
const themes = [
  ['#0b0f1f', '#070912'], ['#0a1a1a', '#050f0f'], ['#1c1016', '#12070c'], ['#1c160a', '#120c07'],
  ['#0f0f1c', '#07070f'], ['#1a1010', '#100707'], ['#0f1c10', '#07120c'], ['#10101c', '#07070f'],
  ['#1c0f1c', '#100510'], ['#0a141c', '#050b0f'], ['#1c1a0a', '#120f05'], ['#101c14', '#07130c'],
  ['#1c1c1c', '#101010'], ['#0b0f1f', '#070912'], ['#1a1a0a', '#100f05'], ['#0f0f1c', '#07070f'],
  ['#1c1016', '#12070c'], ['#0a1a1a', '#050f0f'], ['#1c160a', '#120c07'], ['#0f0f1c', '#07070f'],
];

// ---- enemies (progressive). ground ty = H-2; cannons added later ----
function enemiesFor(i, H) {
  const s = H - 2;
  const L = [
    [{ type: 'patrol', tx: 12, ty: s, dir: -1, speed: 1.4 }],
    [{ type: 'patrol', tx: 22, ty: s, dir: 1, speed: 1.5 }],
    [{ type: 'patrol', tx: 20, ty: s, dir: -1, speed: 1.6 }, { type: 'hopper', tx: 8, ty: s, dir: 1, speed: 1.2 }],
    [{ type: 'patrol', tx: 18, ty: s, dir: 1, speed: 1.7 }, { type: 'hopper', tx: 30, ty: s, dir: -1, speed: 1.3 }],
    [{ type: 'patrol', tx: 20, ty: s, dir: 1, speed: 1.8 }, { type: 'hopper', tx: 10, ty: s, dir: 1, speed: 1.4 }],
    [{ type: 'charger', tx: 26, ty: s, dir: 1, speed: 2.8 }, { type: 'hopper', tx: 14, ty: s, dir: -1, speed: 1.4 }],
    [{ type: 'charger', tx: 30, ty: s, dir: 1, speed: 2.9 }, { type: 'cannon', tx: 12, ty: s, dir: 1, speed: 0, fire: 110 }],
    [{ type: 'charger', tx: 34, ty: s, dir: -1, speed: 3.0 }, { type: 'hopper', tx: 20, ty: s, dir: 1, speed: 1.5 }, { type: 'cannon', tx: 6, ty: s, dir: 1, speed: 0, fire: 100 }],
    [{ type: 'charger', tx: 40, ty: s, dir: 1, speed: 3.1 }, { type: 'hopper', tx: 24, ty: s, dir: -1, speed: 1.5 }, { type: 'chaser', tx: 30, ty: 8, dir: 1, speed: 1.5 }],
    [{ type: 'charger', tx: 30, ty: s, dir: 1, speed: 3.1 }, { type: 'cannon', tx: 14, ty: s, dir: 1, speed: 0, fire: 95 }, { type: 'hopper', tx: 44, ty: s, dir: 1, speed: 1.6 }],
    [{ type: 'charger', tx: 40, ty: s, dir: 1, speed: 3.2 }, { type: 'hopper', tx: 12, ty: s, dir: -1, speed: 1.6 }, { type: 'cannon', tx: 24, ty: s, dir: 1, speed: 0, fire: 90 }],
    [{ type: 'charger', tx: 24, ty: s, dir: 1, speed: 3.2 }, { type: 'chaser', tx: 26, ty: 8, dir: 1, speed: 1.7 }, { type: 'cannon', tx: 8, ty: s, dir: 1, speed: 0, fire: 88 }],
    [{ type: 'charger', tx: 34, ty: s, dir: 1, speed: 3.3 }, { type: 'hopper', tx: 14, ty: s, dir: 1, speed: 1.7 }, { type: 'chaser', tx: 26, ty: 9, dir: 1, speed: 1.8 }, { type: 'cannon', tx: 44, ty: s, dir: 1, speed: 0, fire: 85 }],
    [{ type: 'charger', tx: 44, ty: s, dir: 1, speed: 3.4 }, { type: 'hopper', tx: 16, ty: s, dir: 1, speed: 1.7 }, { type: 'chaser', tx: 30, ty: 9, dir: 1, speed: 1.8 }, { type: 'cannon', tx: 8, ty: s, dir: 1, speed: 0, fire: 80 }],
    [{ type: 'charger', tx: 30, ty: s, dir: 1, speed: 3.4 }, { type: 'hopper', tx: 14, ty: s, dir: 1, speed: 1.7 }, { type: 'chaser', tx: 28, ty: 9, dir: 1, speed: 1.9 }, { type: 'cannon', tx: 48, ty: s, dir: 1, speed: 0, fire: 78 }],
    [{ type: 'charger', tx: 36, ty: s, dir: 1, speed: 3.5 }, { type: 'hopper', tx: 16, ty: s, dir: 1, speed: 1.8 }, { type: 'chaser', tx: 30, ty: 9, dir: 1, speed: 2.0 }, { type: 'cannon', tx: 10, ty: s, dir: 1, speed: 0, fire: 75 }],
  ];
  return L[i] || [];
}

// ---- moving platforms (bonus variety, later levels) ----
function platformsFor(i, W, H) {
  const s = H - 2, p = [];
  if (i === 5) p.push({ x: 30, y: s - 5, w: 2, axis: 'x', range: 128, speed: 0.012, phase: 0 });
  if (i === 7) p.push({ x: 40, y: s - 4, w: 2, axis: 'y', range: 80, speed: 0.012, phase: 0.3 });
  if (i === 9) p.push({ x: 34, y: s - 5, w: 2, axis: 'x', range: 160, speed: 0.012, phase: 0.6 });
  if (i === 10) p.push({ x: 30, y: s - 4, w: 2, axis: 'x', range: 128, speed: 0.012, phase: 0.4 });
  if (i === 11) p.push({ x: 28, y: s - 5, w: 2, axis: 'y', range: 96, speed: 0.013, phase: 0.2 });
  if (i === 12) p.push({ x: 40, y: s - 5, w: 2, axis: 'x', range: 128, speed: 0.013, phase: 0.5 });
  if (i === 13) p.push({ x: 30, y: s - 5, w: 2, axis: 'x', range: 160, speed: 0.013, phase: 0.3 });
  if (i === 14) p.push({ x: 34, y: s - 5, w: 2, axis: 'x', range: 128, speed: 0.013, phase: 0.6 });
  if (i === 15) p.push({ x: 30, y: s - 5, w: 2, axis: 'y', range: 96, speed: 0.014, phase: 0.4 });
  return p;
}

// ---- boss configs per world ----
const bosses = [
  { hp: 6, speed: 1.6, fireInterval: 65, name: 'SLUDGE KING' },
  { hp: 9, speed: 1.9, fireInterval: 52, name: 'TAR TITAN' },
  { hp: 12, speed: 2.2, fireInterval: 42, name: 'GOO GOLEM' },
  { hp: 15, speed: 2.5, fireInterval: 34, name: 'GLOOP GOBBLER' },
];

// ---- validate all 16 normal levels ----
let allOk = true;
normal.forEach(([t, m], i) => {
  const r = validate(m);
  const ok = r.all && r.trophy;
  if (!ok) allOk = false;
  console.log((ok ? 'PASS' : 'FAIL'), 'L' + (i + 1), t, m[0].length + 'x' + m.length, 'coins:' + r.coins, 'all:' + r.all, 'trophy:' + r.trophy);
});
console.log('ALL 16 NORMAL VALID:', allOk);

// ---- assemble 20 levels (16 normal + 4 bosses at 5,10,15,20) ----
let out = '';
function emit(idx, name, isBoss, map, enemies, platforms, theme, boss) {
  out += '    {\n      name: "' + name + '",\n';
  out += '      theme: { c0: "' + theme[0] + '", c1: "' + theme[1] + '" },\n';
  out += '      isBoss: ' + isBoss + ',\n';
  if (boss) out += '      boss: { hp: ' + boss.hp + ', speed: ' + boss.speed + ', fireInterval: ' + boss.fireInterval + ', name: "' + boss.name + '" },\n';
  out += '      map: [\n';
  map.forEach(r => { out += '        "' + r + '",\n'; });
  out = out.replace(/,\n$/, '\n') + '      ],\n      enemies: [\n';
  enemies.forEach(e => {
    out += '        { type: "' + e.type + '", tx: ' + e.tx + ', ty: ' + e.ty + ', dir: ' + e.dir + ', speed: ' + e.speed + (e.fire ? ', fire: ' + e.fire : '') + ' },\n';
  });
  out = out.replace(/,\n$/, '\n') + '      ],\n      platforms: [\n';
  platforms.forEach(p => {
    out += '        { x: ' + p.x + ', y: ' + p.y + ', w: ' + p.w + ', axis: "' + p.axis + '", range: ' + p.range + ', speed: ' + p.speed + ', phase: ' + p.phase + ' },\n';
  });
  out = out.replace(/,\n$/, '\n') + '      ]\n    },\n';
}
let li = 0;
for (let world = 0; world < 4; world++) {
  for (let j = 0; j < 4; j++) {
    const i = world * 4 + j;
    const [t, m] = normal[i];
    const H = m.length, W = m[0].length;
    emit(li, 'Level ' + (li + 1), false, m, enemiesFor(i, H), platformsFor(i, W, H), themes[li]);
    li++;
  }
  // boss at end of world
  const bm = bossMaps[world];
  const H = bm.length;
  emit(li, 'Level ' + (li + 1) + ' - BOSS', true, bm,
    [{ type: 'boss', tx: Math.floor(bm[0].length / 2), ty: 14, dir: 1, speed: bosses[world].speed }],
    [{ x: 20, y: 6, w: 2, axis: 'x', range: 160, speed: 0.015, phase: 0 }],
    themes[li], bosses[world]);
  li++;
}
out = out.replace(/,\n$/, '\n');
require('fs').writeFileSync('levels_block.js', out);
console.log('Wrote levels_block.js with', li, 'levels');

