function enemyName(type) {
  var n = { patrol: 'PATROLLER', charger: 'CHARGER', hopper: 'HOPPER', chaser: 'CHASER', cannon: 'CANNON', boss: 'BOSS' };
  return n[type] || type.toUpperCase();
}

// Big dramatic portrait drawn at the origin (caller sets the transform/scale).
function drawEnemyBig(type) {
  if (type === 'boss') {
    ctx.fillStyle = '#6b2020'; ctx.fillRect(-32, -8, 64, 48);
    ctx.fillStyle = '#8a3030'; ctx.fillRect(-32, -24, 64, 16);
    ctx.fillStyle = '#ffd42a';
    ctx.fillRect(-22, -36, 10, 12); ctx.fillRect(-5, -42, 10, 18); ctx.fillRect(12, -36, 10, 12);
    ctx.fillStyle = '#fff'; ctx.fillRect(-22, -16, 12, 12); ctx.fillRect(10, -16, 12, 12);
    ctx.fillStyle = '#c00'; ctx.fillRect(-18, -13, 6, 6); ctx.fillRect(12, -13, 6, 6);
    ctx.fillStyle = '#200'; ctx.fillRect(-14, 26, 28, 5);
    return;
  }
  if (type === 'cannon') {
    ctx.fillStyle = '#5a606e'; ctx.fillRect(-14, -6, 28, 26);
    ctx.fillStyle = '#7a8190'; ctx.fillRect(-16, -16, 32, 10);
    ctx.fillStyle = '#2a2d33'; ctx.fillRect(8, -4, 16, 10);
    return;
  }
  var colors = {
    patrol: ['#2b7fd4', '#4d9ff0'], charger: ['#d44b2b', '#f07a4d'],
    hopper: ['#8a2bd4', '#b04df0'], chaser: ['#2bd4a0', '#4df0c0']
  };
  var c = colors[type] || ['#ffffff', '#ffffff'];
  ctx.fillStyle = c[1]; ctx.fillRect(-16, -16, 32, 10);
  ctx.fillStyle = c[0]; ctx.fillRect(-16, -6, 32, 22);
  ctx.fillStyle = '#fff'; ctx.fillRect(-14, -10, 8, 8); ctx.fillRect(6, -10, 8, 8);
  ctx.fillStyle = '#111'; ctx.fillRect(-12, -8, 4, 4); ctx.fillRect(8, -8, 4, 4);
}

// Dramatic animated cutscene shown before each enemy fight.
function drawEnemyIntro() {
  if (introEnemies.length === 0) return;
  var type = introEnemies[introIndex].type;
  var phase = 1 - (introTimer / ENEMY_INTRO_FRAMES); // 0..1
  var isBoss = type === 'boss';

  // Dark scene with a pulsing radial glow.
  ctx.fillStyle = 'rgba(4,5,10,0.96)'; ctx.fillRect(0, 0, CANVAS_W, CANVAS_H);
  var pulse = Math.abs(Math.sin(phase * Math.PI * 8));
  var glow = ctx.createRadialGradient(CANVAS_W / 2, CANVAS_H / 2 - 40, 10, CANVAS_W / 2, CANVAS_H / 2 - 40, 320);
  glow.addColorStop(0, isBoss ? 'rgba(160,40,30,' + (0.25 + pulse * 0.2) + ')' : 'rgba(120,120,200,' + (0.18 + pulse * 0.15) + ')');
  glow.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = glow; ctx.fillRect(0, 0, CANVAS_W, CANVAS_H);

  // The enemy zooms in with a slight shake.
  var scale = Math.min(4, 1 + phase * 3);
  var shake = (1 - phase) * 6 * Math.sin(phase * Math.PI * 30);
  var cx = CANVAS_W / 2 + shake, cy = CANVAS_H / 2 - 20;
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);
  drawEnemyBig(type);
  ctx.restore();

  // Name flashes in with a dramatic reveal.
  ctx.textAlign = 'center';
  var name = isBoss ? bossConfig().name : enemyName(type);
  ctx.fillStyle = isBoss ? '#ff6a2b' : '#ffd42a';
  ctx.font = 'bold ' + (isBoss ? 40 : 36) + 'px "Courier New", monospace';
  ctx.globalAlpha = Math.min(1, phase * 4);
  ctx.fillText(name, CANVAS_W / 2, cy + 120);
  ctx.globalAlpha = 1;

  ctx.fillStyle = '#fff';
  ctx.font = 'bold 16px "Courier New", monospace';
  ctx.fillText(isBoss ? 'THE BOSS APPROACHES!' : 'ENEMY APPROACHING!', CANVAS_W / 2, cy + 148);
  ctx.fillStyle = '#6b7390';
  ctx.font = '12px "Courier New", monospace';
  ctx.fillText('Press SPACE to skip', CANVAS_W / 2, 320);
  ctx.textAlign = 'left';
}

function drawHUD() {

