if (climbing) {
  player.x = ladderCol * TS + (TS - player.w) / 2;
  player.vx = 0; player.vy = 0; player.onGround = false;
  if (climbUp) { var ny = player.y - CLIMB_SPEED; if (!isSolid(tileAt(player.x + player.w / 2, ny))) player.y = ny; }
  if (climbDown) { var ny2 = player.y + CLIMB_SPEED; if (!isSolid(tileAt(player.x + player.w / 2, ny2 + player.h - 1))) player.y = ny2; }
  if (jumpPressed) { climbing = false; player.vy = JUMP_VY; }
  else if (move !== 0) { climbing = false; player.vx = move * effectiveSpeed(); player.onGround = false; }
} else {
  // Ice: low friction -> keep sliding when no input.
  var tileBelow = tileAt(player.x + player.w / 2, player.y + player.h + 1);
  var onIce = player.onGround && tileBelow === ICE;
  if (move !== 0) player.vx = move * effectiveSpeed();
  else if (!onIce) player.vx = 0;
  // (keep last vx on ice)
  if (move !== 0) player.facing = move;
  player.vy += GRAVITY;
  if (player.vy > MAX_FALL) player.vy = MAX_FALL;
  if (player.onGround) coyote = COYOTE_FRAMES;
  else if (coyote > 0) coyote--;
  if (jumpPressed) jumpBuffer = BUFFER_FRAMES;
  else if (jumpBuffer > 0) jumpBuffer--;
  if (jumpBuffer > 0) {
    if (coyote > 0) { player.vy = JUMP_VY; player.onGround = false; coyote = 0; jumpBuffer = 0; player.jumpsUsed = 1; }
    else if (player.jumpsUsed === 1 && player.doubleTimer > 0) { player.vy = JUMP_VY; player.onGround = false; jumpBuffer = 0; player.jumpsUsed = 2; }
  }
  player.onGround = false;
  player.x += player.vx; horizontalCollide(player);
  player.y += player.vy; verticalCollide(player, true);
}
// Conveyor belts push the player.
var cv = tileAt(player.x + player.w / 2, player.y + player.h + 1);
if (cv === CONV_R) player.x += 1.5;
else if (cv === CONV_L) player.x -= 1.5;

