function horizontalCollide(obj) {
  var left = Math.floor(obj.x / TS), right = Math.floor((obj.x + obj.w - 1) / TS);
  var top = Math.floor(obj.y / TS), bottom = Math.floor((obj.y + obj.h - 1) / TS);
  for (var ty = top; ty <= bottom; ty++) {
    var tr = tileAt(right * TS, ty * TS), tl = tileAt(left * TS, ty * TS);
    if (obj.vx > 0 && solidSide(tr)) { obj.x = right * TS - obj.w - 0.01; obj.vx = 0; }
    else if (obj.vx < 0 && solidSide(tl)) { obj.x = (left + 1) * TS + 0.01; obj.vx = 0; }
  }
}
function verticalCollide(obj, useSpring) {
  var left = Math.floor(obj.x / TS), right = Math.floor((obj.x + obj.w - 1) / TS);
  var top = Math.floor(obj.y / TS), bottom = Math.floor((obj.y + obj.h - 1) / TS);
  var spring = false;
  for (var tx = left; tx <= right; tx++) {
    var tt = tileAt(tx * TS, top * TS), tb = tileAt(tx * TS, bottom * TS);
    // landing: solid from below OR a one-way platform (only when falling)
    if (obj.vy > 0 && (isSolid(tb) || tb === ONEWAY)) {
      obj.y = bottom * TS - obj.h - 0.01;
      if (tb === SPRING) { obj.vy = SPRING_VY; obj.onGround = false; }
      else if (useSpring && tb === BOUNCY) { obj.vy = -19; obj.onGround = false; }
      else if (useSpring && tb === TRAMPOLINE) { obj.vy = -28; obj.onGround = false; }
      else if (useSpring && tb === CRATE) { grid[Math.floor((obj.y + obj.h - 0.01) / TS)][tx] = EMPTY; obj.vy = 1; }
      else { obj.vy = 0; obj.onGround = true; }
    } else if (obj.vy < 0 && isSolid(tt)) {
      obj.y = (top + 1) * TS + 0.01; obj.vy = 0;
    }
  }
}

