input.newString:
function findTeleporter(which) {
  for (var r = 0; r < levelH; r++) for (var c = 0; c < levelW; c++) if (grid[r][c] === which) return { x: c * TS, y: r * TS };
  return null;
}

function checkTileInteractions() {
  var left = Math.floor(player.x / TS), right = Math.floor((player.x + player.w - 1) / TS);
  var top = Math.floor(player.y / TS), bottom = Math.floor((player.y + player.h - 1) / TS);
  for (var ty = top; ty <= bottom; ty++) for (var tx = left; tx <= right; tx++) {
    var tile = (ty >= 0 && ty < levelH && tx >= 0 && tx < levelW) ? grid[ty][tx] : EMPTY;
    switch (tile) {
      case SPIKE: if (spikeActive()) takeDamage(); return;
      case LAVA: case MINE: case SAW: takeDamage(); return;
      case COIN: grid[ty][tx] = EMPTY; coinsCollected++; player.score += 10; break;
      case HEART: grid[ty][tx] = EMPTY; if (lives < 5) lives++; break;
      case STAR: grid[ty][tx] = EMPTY; starTimer = STAR_DURATION; break;
      case SPEED: grid[ty][tx] = EMPTY; player.speedTimer = SPEED_DURATION; break;
      case DOUBLE: grid[ty][tx] = EMPTY; player.doubleTimer = DOUBLE_DURATION; break;
      case KEY: grid[ty][tx] = EMPTY; player.key++; break;
      case DOOR: if (player.key > 0) { grid[ty][tx] = EMPTY; player.key--; } break;
      case TELEA: { grid[ty][tx] = EMPTY; var d = findTeleporter(TELEB); if (d) { player.x = d.x; player.y = d.y; player.vy = 0; } break; }
      case TELEB: { grid[ty][tx] = EMPTY; var a = findTeleporter(TELEA); if (a) { player.x = a.x; player.y = a.y; player.vy = 0; } break; }
      case CHECKPOINT: player.respawn = { x: tx * TS, y: ty * TS - TS }; break;
      case GEM: grid[ty][tx] = EMPTY; player.score += 50; break;
      case GOLD: grid[ty][tx] = EMPTY; player.score += 100; break;
      case SHIELD: grid[ty][tx] = EMPTY; player.shieldTimer = 300; break;
      case MAGNET: grid[ty][tx] = EMPTY; player.magnetTimer = 300; break;
      case TROPHY: if (!isBossLevel() && coinsCollected >= coinsNeeded) { levelClear(); return; } break;
    }
  }
}

// Magnet power-up pulls nearby coins to the player.
function applyMagnet() {
  if (player.magnetTimer <= 0) return;
  var pr = 5 * TS;
  for (var r = 0; r < levelH; r++) for (var c = 0; c < levelW; c++) {
    if (grid[r][c] === COIN) {
      var cx = c * TS + TS / 2, cy = r * TS + TS / 2;
      var px = player.x + player.w / 2, py = player.y + player.h / 2;
      if (Math.abs(cx - px) < pr && Math.abs(cy - py) < pr) { grid[r][c] = EMPTY; coinsCollected++; player.score += 10; }
    }
  }
}

function takeDamage() {
  if (state !== 'playing') return;
  if (starTimer > 0 || invulnTimer > 0) return;
  if (player.shieldTimer > 0) { player.shieldTimer = 0; invulnTimer = INVULN_DURATION; return; }
  lives--;
  if (lives <= 0) { state = 'gameover'; return; }
  invulnTimer = INVULN_DURATION; deathTimer = 10;
  // Respawn at the last checkpoint (or start), keep coins.
  player.x = player.respawn.x; player.y = player.respawn.y; player.vy = 0; player.vx = 0;
  climbing = false;
}

