function updateEnemies() {
  for (var i = 0; i < enemies.length; i++) {
    var e = enemies[i];
    if (!e.alive) continue;
    if (e.type === 'chaser') updateChaser(e);
    else if (e.type === 'cannon') updateCannon(e);
    else if (e.type === 'fireball') updateFireball(e);
    else if (e.type === 'ghost') updateGhost(e);
    else if (e.type === 'mole') updateMole(e);
    else if (e.type === 'flyer') updateFlyer(e);
    else updateGroundEnemy(e);
    checkEnemyPlayerCollision(e);
  }
}

function updateFireball(e) {
  e.vy += GRAVITY; if (e.vy > MAX_FALL) e.vy = MAX_FALL;
  var ahead = e.dir > 0 ? e.x + e.w + 1 : e.x - 1;
  if (solidSide(tileAt(ahead, e.y + e.h / 2))) e.dir *= -1;
  e.x += e.dir * e.speed;
  e.onGround = false; e.y += e.vy; verticalCollide(e, false);
  if (e.onGround) { e.vy = -13; }
}

function updateGhost(e) {
  e.time += 0.05;
  var dx = player.x - e.x, dy = player.y - e.y;
  var len = Math.sqrt(dx * dx + dy * dy) || 1;
  e.x += dx / len * e.speed; e.y += dy / len * e.speed;
  e.dir = dx > 0 ? 1 : -1;
  if (e.x < 0) e.x = 0; if (e.x + e.w > levelW * TS) e.x = levelW * TS - e.w;
  if (e.y < 0) e.y = 0; if (e.y + e.h > levelH * TS) e.y = levelH * TS - e.h;
}

function updateMole(e) {
  e.popTimer++;
  e.hidden = (e.popTimer % 100) > 60;
}

function updateFlyer(e) {
  e.time += 0.05;
  e.y = e.baseY + Math.sin(e.time) * 40;
  e.dir = player.x > e.x ? 1 : -1;
  e.x += e.dir * e.speed * 0.3;
  if (e.x < 0) e.x = 0; if (e.x + e.w > levelW * TS) e.x = levelW * TS - e.w;
}

