const fs=require('fs');
let code=fs.readFileSync('gloop-escape.html','utf8').match(/<script>([\s\S]*?)<\/script>/)[1];
const hook='window.__g={get player(){return player;},get enemies(){return enemies;},get state(){return state;},get levelIndex(){return levelIndex;},get boss(){return boss;},get projectiles(){return projectiles;},get lives(){return lives;},loadLevel:loadLevel};';
code=code.replace(/\}\)\(\);\s*$/, hook+'\n})();');
function rgrad(){return {addColorStop:()=>{}};}
const ctxStub=new Proxy({}, {get:(t,p)=>{ if(p==='createLinearGradient'||p==='createRadialGradient')return rgrad; return ()=>({}); }, set:()=>true});
const canvasStub={getContext:()=>ctxStub};
const listeners={};
global.document={getElementById:()=>canvasStub};
let raf=null; global.requestAnimationFrame=(fn)=>{raf=fn;};
const wnd={addEventListener:(ev,fn)=>{listeners[ev]=fn;}};
global.window=wnd;
new Function('document','requestAnimationFrame','window', code)(global.document, global.requestAnimationFrame, wnd);
const g=wnd.__g;
let t=0; const step=(n)=>{for(let i=0;i<n;i++){t+=16.66; raf&&raf(t);}};
const key=(c)=>{listeners['keydown']&&listeners['keydown']({code:c,preventDefault:()=>{}});};
const unkey=(c)=>{listeners['keyup']&&listeners['keyup']({code:c});};
// Simulate actual gameplay: hold right + jump on each level
let issues=0;
for(let lv=0;lv<30;lv++){
  g.loadLevel(lv);
  // skip intro
  for(let i=0;i<250;i++) step(1);
  key('ArrowRight');
  for(let f=0;f<400;f++){
    if(f%40===0) key('Space');
    if(f%40===10) unkey('Space');
    step(1);
    const p=g.player;
    if(!isFinite(p.x)||!isFinite(p.y)){ issues++; console.log('L'+(lv+1)+' NaN pos'); break; }
    if(p.y< -5000 || p.x< -5000 || p.x>5000){ issues++; console.log('L'+(lv+1)+' out of bounds', p.x.toFixed(0), p.y.toFixed(0)); break; }
  }
  unkey('ArrowRight'); unkey('Space');
}
console.log('Gameplay sim issues:', issues);
console.log('All levels sim finished');
"

