//  BOSS CINEMATIC — unique ~30s animated intro per boss
// ------------------------------------------------------------------
function bossShotIndex() {
  var total = 0; var shots = (boss && boss.intro) || [];
  var elapsed = (boss && boss.introTotal || 0) - introTimer;
  for (var i = 0; i < shots.length; i++) { total += shots[i].d; if (elapsed < total) return { idx: i, elapsed: elapsed - (total - shots[i].d), shot: shots[i] }; }
  return { idx: shots.length - 1, elapsed: 0, shot: shots[shots.length - 1] };
}

function drawBossCinematic() {
  var shots = (boss && boss.intro) || [];
  if (!shots.length) { drawEnemyShot('boss'); return; }
  var s = bossShotIndex();
  var d = s.shot.d, e = s.elapsed;
  var p = Math.min(1, e / d); // 0..1 within shot
  var skin = boss.skin;
  var name = boss.name;
  var cx = CANVAS_W / 2, cy = CANVAS_H / 2 - 20;

  // dark base
  ctx.fillStyle = 'rgba(3,3,8,0.97)'; ctx.fillRect(0, 0, CANVAS_W, CANVAS_H);

  switch (s.shot.t) {
