      // Boss zooms in from far away.
      var sc = 0.2 + p * 3.2;
      ctx.fillStyle = 'rgba(120,120,200,' + (0.1 + p * 0.15) + ')';
      ctx.fillRect(0, 0, CANVAS_W, CANVAS_H);
      ctx.save(); ctx.translate(cx, cy + 45); ctx.scale(sc, sc); drawBossBody(skin, 0, 0, 1); ctx.restore();
      ctx.textAlign = 'center'; ctx.fillStyle = '#fff'; ctx.font = 'bold 26px "Courier New", monospace'; ctx.fillText('Something stirs...', cx, 360); ctx.textAlign = 'left';
      break;
    }
    case 'eyes': {
      // Only glowing eyes in the dark, growing.
      var r = 4 + p * 20;
      ctx.fillStyle = skin === 1 ? '#ff9a2b' : (skin === 2 ? '#ff3a2b' : '#ffd42a');
      ctx.beginPath(); ctx.arc(cx - 70, cy - 20, r, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(cx + 70, cy - 20, r, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = 'rgba(0,0,0,' + (0.6 * Math.sin(p * Math.PI)) + ')'; ctx.fillRect(0, 0, CANVAS_W, CANVAS_H);
      ctx.textAlign = 'center'; ctx.fillStyle = '#666'; ctx.font = 'bold 20px "Courier New", monospace'; ctx.fillText('...', cx, 200); ctx.textAlign = 'left';
