function drawGobblerCinematic() {
    var p = Math.min(1, (boss.introTotal - introTimer) / boss.introTotal);
    var cx = CANVAS_W / 2, cy = CANVAS_H / 2;
    ctx.fillStyle = 'rgba(4,3,8,0.97)'; ctx.fillRect(0, 0, CANVAS_W, CANVAS_H);
    // 1) glowing eyes in the dark
    var eye = Math.min(1, p / 0.3);
    ctx.fillStyle = '#7a2bd4'; ctx.beginPath(); ctx.arc(cx - 60, cy - 40, 6 * eye, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.arc(cx + 60, cy - 40, 6 * eye, 0, Math.PI * 2); ctx.fill();
    // 2) the maw opens (widening arc with teeth)
    var open = Math.max(0, (p - 0.25) / 0.35);
    var mouthH = open * 90, mouthW = 40 + open * 120;
    ctx.fillStyle = '#3a0a50'; ctx.beginPath(); ctx.ellipse(cx, cy + 40, mouthW, mouthH, 0, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#000'; ctx.beginPath(); ctx.ellipse(cx, cy + 46, mouthW * 0.7, mouthH * 0.7, 0, 0, Math.PI * 2); ctx.fill();
    // teeth ring
    ctx.fillStyle = '#fff';
    for (var t = -9; t <= 9; t++) { ctx.fillRect(cx + t * (mouthW / 11) - 3, cy + 40 - mouthH - 4, 5, 8); }
    // 3) inhale: debris flies into the mouth
    if (open > 0.6) {
      var inh = Math.max(0, (p - 0.6) / 0.2);
      for (var d2 = 0; d2 < 14; d2++) {
        var da = d2 * 2.6 + p * 8; var dist = (1 - inh) * 300 + 20;
        var dx = cx + Math.cos(da) * dist, dy = cy + Math.sin(da) * dist * 0.7;
        var tw = 0.4 + Math.abs(Math.sin(d2 + p * 20)) * 0.6;
        ctx.fillStyle = 'rgba(150,150,160,' + tw + ')';
        ctx.save(); ctx.translate(dx, dy); ctx.rotate(da * 2); ctx.fillRect(-4, -4, 8, 8); ctx.restore();
      }
      ctx.fillStyle = 'rgba(122,43,212,0.4)';
      for (var sw = 0; sw < 3; sw++) { ctx.beginPath(); ctx.arc(cx, cy + 40, (sw * 30 + 20) * (1 - inh), 0, Math.PI * 2); ctx.fill(); }
    }
    // 4) roar + purple shockwave
    if (p > 0.82) {
      var roar = Math.min(1, (p - 0.82) / 0.1);
      var pulse = Math.abs(Math.sin(p * 30));
      ctx.strokeStyle = 'rgba(122,43,212,' + roar * (0.4 + pulse * 0.6) + ')'; ctx.lineWidth = 6;
      for (var rw = 0; rw < 3; rw++) { ctx.beginPath(); ctx.arc(cx, cy + 40, (40 + rw * 30) * roar + 20, 0, Math.PI * 2); ctx.stroke(); }
    }
    if (p > 0.92) {
      ctx.textAlign = 'center'; ctx.fillStyle = '#7a2bd4'; ctx.font = 'bold 42px "Courier New", monospace'; ctx.globalAlpha = Math.min(1, (p - 0.92) * 8);
      ctx.fillText(boss.name, cx, cy - 40); ctx.globalAlpha = 1;
      ctx.fillStyle = '#fff'; ctx.font = 'bold 16px "Courier New", monospace'; ctx.fillText('IT WILL DEVOUR ALL!', cx, cy + 200); ctx.textAlign = 'left';
    }
    ctx.fillStyle = '#555'; ctx.font = '11px "Courier New", monospace'; ctx.fillText('Press SPACE to skip', CANVAS_W / 2 - 60, CANVAS_H - 10);
  }

