      ctx.fillText('UP / DOWN on ladders - climb', 170, 182);
      ctx.fillText('ESC / P or button - pause', 170, 209);
      ctx.fillText('R - restart current level', 170, 236);
      ctx.fillText('@ - (dev) skip the level', 170, 263);
      ctx.fillStyle = '#888'; ctx.font = '13px "Courier New", monospace';
