      ctx.fillText('Gloop has been captured by the enemy horde!', CANVAS_W / 2, 160);
      ctx.fillText('Collect every coin, reach the trophy,', CANVAS_W / 2, 182);
      ctx.fillText('and defeat the bosses to escape.', CANVAS_W / 2, 204);
      ctx.fillText('6 worlds of pixel platforming await.', CANVAS_W / 2, 246);
      ctx.fillStyle = '#888'; ctx.font = '13px "Courier New", monospace';
      ctx.fillText('click again to close', CANVAS_W / 2, 320); ctx.textAlign = 'left';
    }

    // ---- Glowing pong ball ----
    var bt = spikeTimer * 0.045;
    var bx = (CANVAS_W / 2) + Math.sin(bt * 0.9) * (CANVAS_W / 2 - 50);
    var by = 360 + Math.sin(bt * 1.6) * 40;
    ctx.fillStyle = 'rgba(255,42,255,0.25)'; ctx.beginPath(); ctx.arc(bx, by, 14, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#ff2aff'; ctx.beginPath(); ctx.arc(bx, by, 7, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#fff'; ctx.beginPath(); ctx.arc(bx - 2, by - 2, 2, 0, Math.PI * 2); ctx.fill();

    // ---- Blinking start prompt ----
    if (Math.floor(spikeTimer / 28) % 2 === 0) {
