function updateTitleDemo() {
  titleGloop.time += 0.05;
  // Gloop flees the swarm centroid.
  var ax = 0, ay = 0;
  for (var i = 0; i < titleEnemies.length; i++) { ax += titleEnemies[i].x; ay += titleEnemies[i].y; }
  ax /= titleEnemies.length; ay /= titleEnemies.length;
  var dx = titleGloop.x - ax, dy = titleGloop.y - ay;
  var len = Math.sqrt(dx * dx + dy * dy) || 1;
  titleGloop.x += dx / len * 2.6; titleGloop.y += dy / len * 2.6;
  titleGloop.dir = dx > 0 ? 1 : -1;
  // TUNNEL: wrap around all edges.
  wrapActor(titleGloop);

  // Enemies chase AND fire unique projectiles.
  for (var j = 0; j < titleEnemies.length; j++) {
    var e = titleEnemies[j]; e.time += 0.05;
    var ex = titleGloop.x - e.x, ey = titleGloop.y - e.y;
    var el = Math.sqrt(ex * ex + ey * ey) || 1;
    var sp = e.type === 'charger' ? 2.4 : (e.type === 'chaser' ? 2.0 : 1.6);
    e.x += ex / el * sp; e.y += ey / el * sp;
    e.dir = ex > 0 ? 1 : -1;
    wrapActor(e);
    // fire unique shot toward Gloop
    e.fire--;
    if (e.fire <= 0 && titleShots.length < 40) {
      e.fire = 100 + (e.type.length * 17) % 60;
      var ang = Math.atan2(titleGloop.y - (e.y + 16), titleGloop.x - (e.x + 16));
      var st = titleShotStyles[e.type];
      titleShots.push({ x: e.x + 16, y: e.y + 16, vx: Math.cos(ang) * st.speed, vy: Math.sin(ang) * st.speed, type: e.type, style: st, alive: true });
    }
  }

  // Update shots.
  for (var s = titleShots.length - 1; s >= 0; s--) {
    var sh = titleShots[s];
    if (sh.style.homing) {
      var ha = Math.atan2(titleGloop.y - sh.y, titleGloop.x - sh.x);
      sh.vx += (Math.cos(ha) * sh.style.speed - sh.vx) * 0.08;
      sh.vy += (Math.sin(ha) * sh.style.speed - sh.vy) * 0.08;
    }
    sh.x += sh.vx; sh.y += sh.vy;
    if (sh.style.bounce) { if (sh.y < 4 || sh.y > CANVAS_H - 4) sh.vy *= -1; }
    if (sh.x < -30) sh.x = CANVAS_W + 20; if (sh.x > CANVAS_W + 30) sh.x = -20;
    if (sh.y < -30) sh.y = CANVAS_H + 20; if (sh.y > CANVAS_H + 30) sh.y = -20;
  }
}

function wrapActor(o) {
  if (o.x < -30) o.x = CANVAS_W + 20; if (o.x > CANVAS_W + 30) o.x = -20;
  if (o.y < -30) o.y = CANVAS_H + 20; if (o.y > CANVAS_H + 30) o.y = -20;
}
