  push(zigzag, 'zigzag', [56, 17, [11, 7, 3], 11], { spikes: [20, 32] });
  push(pitgauntlet, 'pit', [64, 15, [[8, 9], [18, 19], [28, 29], [38, 39], [48, 49]]], { spikes: [14, 24, 44] });
