  push(islands, 'islands', [68, 18, [{ x: 6, y: 14, w: 6 }, { x: 14, y: 11, w: 6 }, { x: 22, y: 8, w: 6 }, { x: 30, y: 5, w: 6 }, { x: 38, y: 2, w: 6 }]], { spikes: [50, 54] });
  push(staircase, 'stair', [60, 17, [12, 8, 4], 11], { spikes: [20, 24, 40, 44], springs: [28] });
  // World 3
