parts.text:
The user wants sound effects for everything. I need to add sound effects using the Web Audio API (no external files). Let me create a sound system using oscillators/noise to generate retro SFX for:
- Jump
- Coin collect
- Powerup (star, speed, double, shield, magnet, glider, heart)
- Stomp/kill enemy
- Player damage
- Spike/hazard
- Spring bounce
- Boss hit
- Boss death / victory
- Game over
- Menu select / navigate
- Level complete
- Title start
- Pause
- Maybe coin drop
- Melee boss attack

Let me implement a Web Audio sound system:
1. Create an AudioContext (lazily on first user interaction, since browsers require a gesture).
2. A function `sfx(type)` that plays a generated sound (oscillator + gain envelope, or noise for explosions).
3. Hook `sfx()` calls into the existing game events (jump, collect, etc.).

Let me build a robust SFX generator:

```
var audioCtx = null;
function ensureAudio(){ if(!audioCtx){ try{ audioCtx = new (window.AudioContext||window.webkitAudioContext)(); }catch(e){} } if(audioCtx && audioCtx.state==='suspended') audioCtx.resume(); }
```

Then a helper to play tones:
```
function tone(freq, start, dur, type, vol, slideTo){
  if(!audioCtx) return;
  var o=audioCtx.createOscillator(); var g=audioCtx.createGain();
  o.type=type||'square'; o.frequency.setValueAtTime(freq, audioCtx.currentTime+start);
  if(slideTo) o.frequency.exponentialRampToValueAtTime(slideTo, audioCtx.currentTime+start+dur);
  g.gain.setValueAtTime(0.0001, audioCtx.currentTime+start);
  g.gain.exponentialRampToValueAtTime(vol, audioCtx.currentTime+start+0.01);
  g.gain.exponentialRampToValueAtTime(0.0001, audioCtx.currentTime+start+dur);
  o.connect(g); g.connect(audioCtx.destination);
  o.start(audioCtx.currentTime+start); o.stop(audioCtx.currentTime+start+dur+0.02);
}
function noise(dur, vol){
  if(!audioCtx) return;
  var buffer=audioCtx.createBuffer(1, audioCtx.sampleRate*dur, audioCtx.sampleRate);
  var data=buffer.getChannelData(0);
  for(var i=0;i<data.length;i++) data[i]=Math.random()*2-1;
  var src=audioCtx.createBufferSource(); src.buffer=buffer;
  var g=audioCtx.createGain(); g.gain.setValueAtTime(vol,audioCtx.currentTime);
  g.gain.exponentialRampToValueAtTime(0.0001,audioCtx.currentTime+dur);
  var f=audioCtx.createBiquadFilter(); f.type='lowpass'; f.frequency.value=2000;
  src.connect(f); f.connect(g); g.connect(audioCtx.destination); src.start();
}
```

Then `sfx(name)` maps names to sequences:
- jump: tone(300,0,0.2,'square',0.2,600)
- coin: tone(900,0,0.08,'square',0.15); tone(1400,0.08,0.15,'square',0.15)
- powerup: rising arpeggio
- stomp: noise short + low tone
- damage: low buzz
- spring: rising tone
- bossHit: tone
- etc.

Let me define sfx:
```
function sfx(name){
  ensureAudio(); if(!audioCtx) return;
  var now=audioCtx.currentTime;
  switch(name){
    case 'jump': tone(300,0,0.15,'square',0.15,520); break;
    case 'coin': tone(880,0,0.06,'square',0.12); tone(1320,0.06,0.1,'square',0.12); break;
    case 'powerup': tone(500,0,0.07,'square',0.14); tone(700,0.07,0.07,'square',0.14); tone(1000,0.14,0.12,'square',0.14); break;
    case 'stomp': noise(0.12,0.2); tone(200,0,0.12,'square',0.15,80); break;
    case 'damage': noise(0.2,0.25); tone(180,0,0.2,'sawtooth',0.2,60); break;
    case 'spring': tone(200,0,0.3,'square',0.2,800); break;
    case 'bossHit': tone(700,0,0.08,'square',0.2); tone(500,0.08,0.12,'square',0.2); break;
    case 'win': arpeggio; break;
    case 'gameover': descending; break;
    case 'select': tone(600,0,0.06,'square',0.12); break;
    case 'menu': tone(400,0,0.08,'square',0.12,700); break;
    case 'levelclear': arpeggio; break;
    case 'glide': tone(300,0,0.15,'triangle',0.1,200); break;
    case 'climb': tone(500,0,0.05,'square',0.05,600); break; (maybe too frequent)
    default: break;
  }
}
```

Then hook sfx() into the game:
- jump: in updatePlayer when jump executes.
- coin: checkTileInteractions COIN case.
- heart/star/speed/double/shield/magnet/glider: powerup sfx.
- gem/gold: coin sfx.
- stomp enemy: checkEnemyPlayerCollision when enemy killed.
- damage: takeDamage.
- spring/bouncy/trampoline: spring sfx.
- boss hit: bossHurt.
- boss death / victory: win sfx.
- gameover: gameover sfx.
- menu select/navigate: select/menu sfx.
- level clear: levelclear sfx.
- title start: menu sfx.
- pause: menu sfx.

Let me add the sound system and hook the sfx calls.

Let me place the sound system near the top (after constants/canvas setup). And ensureAudio is called on first keydown/click (browsers need a gesture). I'll call ensureAudio() in the keydown handler and click handler.

Let me implement:
1. Add sound system (audioCtx, ensureAudio, tone, noise, sfx).
2. Call ensureAudio() on keydown/click.
3. Add sfx() calls at events.

Let me be careful not to spam sounds (e.g., climbing each frame). Only on discrete events.

Let me add the sound system after the canvas setup (after `ctx.imageSmoothingEnabled = false;`).

Let me find that.

Then hook sfx calls:
- keydown: call ensureAudio() (for gesture unlock). And sfx('select') on menu navigation, sfx('menu') on pause, etc.
- updatePlayer jump: sfx('jump') when jump executes.
- checkTileInteractions: coin → sfx('coin'); heart/star/speed/double/shield/magnet/glider → sfx('powerup'); gem/gold → sfx('coin'); key → sfx('coin').
- checkEnemyPlayerCollision: on enemy killed (stomp/star) → sfx('stomp').
- takeDamage: sfx('damage').
- verticalCollide spring/bouncy/trampoline → sfx('spring').
- bossHurt: sfx('bossHit').
- levelClear: sfx('levelclear').
- victory (rat death → victory): sfx('win').
- gameover: sfx('gameover').
- menu select: sfx('select').
- pause/resume: sfx('menu').

Let me implement. Let me be thorough but avoid too many hooks.

