    ctx.fillStyle='rgba(255,60,40,'+gl*0.8+')'; ctx.fillRect(cx-12, cy-10, 24, 4);
    ctx.fillStyle='rgba(255,60,40,'+(0.2+t*0.4)+')'; ctx.fillRect(0,0,CANVAS_W,CANVAS_H);
  } else if(phase===4){ // cape + march
    ctx.fillStyle='rgba(138,32,32,'+(0.2+t*0.5)+')';
    ctx.beginPath(); ctx.moveTo(cx-20, cy+50); ctx.quadraticCurveTo(cx-40, cy+20+Math.sin(t*10)*8, cx-24, cy-10); ctx.lineTo(cx-8, cy+30); ctx.closePath(); ctx.fill();
    ctx.save(); ctx.translate(cx,cy+50); ctx.scale(1.3,1.3); drawBossBody(5,0,0,1); ctx.restore();
    ctx.textAlign='center'; ctx.fillStyle='#ccc'; ctx.font='bold 22px "Courier New",monospace'; ctx.fillText('FOR HONOR!', cx, cy+160); ctx.textAlign='left';
  } else { // name reveal
    rays + drawBossBody + name
  }
  ctx.fillStyle='#555'; ctx.font='11px "Courier New",monospace'; ctx.fillText('Press SPACE to skip', CANVAS_W/2-60, CANVAS_H-10);
}
