function drawEnemy(e) {
  if (!e.alive) return;
  var x = Math.round(e.x), y = Math.round(e.y);
  var cx = x + TS / 2, cy = y + TS / 2;
  var f = e.dir > 0 ? 1 : -1;

  if (e.type === 'cannon') {
    ctx.fillStyle = '#5a606e'; ctx.fillRect(x + 4, y + 14, TS - 8, TS - 16);
    ctx.fillStyle = '#7a8190'; ctx.fillRect(x, y, TS, 8);
    ctx.fillStyle = '#3a3e46'; ctx.fillRect(x + 4, y + TS - 8, TS - 8, 4);
    var ang = Math.atan2((player.y + player.h / 2) - cy, (player.x + player.w / 2) - cx);
    ctx.save(); ctx.translate(cx, cy); ctx.rotate(ang);
    ctx.fillStyle = '#2a2d33'; ctx.fillRect(6, -4, 12, 8); ctx.fillStyle = '#111'; ctx.fillRect(16, -3, 4, 6);
    ctx.restore();
    return;
  }

  if (e.type === 'patrol') {
    // Round slime blob with two antennae.
    ctx.fillStyle = '#1a4d80'; ctx.fillRect(x + 6, y + 24, 8, 4); ctx.fillRect(x + 18, y + 24, 8, 4);
    ctx.fillStyle = '#2b7fd4'; ctx.beginPath(); ctx.arc(cx, y + 18, 13, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#4d9ff0'; ctx.beginPath(); ctx.arc(cx, y + 13, 9, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#2b7fd4'; ctx.fillRect(cx - 6, y + 2, 3, 6); ctx.fillRect(cx + 3, y + 2, 3, 6);
    ctx.fillStyle = '#ffd42a'; ctx.beginPath(); ctx.arc(cx - 6, y + 1, 2, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.arc(cx + 3, y + 1, 2, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#0c2a44'; ctx.beginPath(); ctx.arc(cx - 5 + f * 2, y + 18, 4, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.arc(cx + 5 + f * 2, y + 18, 4, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#fff'; ctx.beginPath(); ctx.arc(cx - 6 + f * 2, y + 17, 1.5, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.arc(cx + 4 + f * 2, y + 17, 1.5, 0, Math.PI * 2); ctx.fill();
    return;
  }

  if (e.type === 'charger') {
    // Angular horned beast pointing the direction it runs.
    ctx.fillStyle = '#802b1a'; ctx.fillRect(x + 6, y + 26, 10, 4); ctx.fillRect(x + 16, y + 26, 10, 4);
    ctx.fillStyle = '#d44b2b'; ctx.beginPath();
    ctx.moveTo(x + (f > 0 ? TS - 2 : 2), cy + 2);
    ctx.lineTo(x + (f > 0 ? 2 : TS - 2), y + 6);
    ctx.lineTo(x + (f > 0 ? 2 : TS - 2), y + 22);
    ctx.closePath(); ctx.fill();
    ctx.fillStyle = '#f07a4d'; ctx.fillRect(x + (f > 0 ? 8 : TS - 16), y + 10, 10, 8);
    ctx.fillStyle = '#fff'; ctx.beginPath();
    ctx.moveTo(x + (f > 0 ? TS - 2 : 2), y + 4); ctx.lineTo(x + (f > 0 ? TS - 12 : 12), y + 6); ctx.lineTo(x + (f > 0 ? TS - 2 : 2), y + 10); ctx.closePath(); ctx.fill();
    ctx.fillStyle = '#3a100a'; ctx.beginPath(); ctx.arc(x + (f > 0 ? 8 : TS - 8), y + 14, 3, 0, Math.PI * 2); ctx.fill();
    return;
  }

  if (e.type === 'hopper') {
    // Round top with big springy coil legs.
    ctx.fillStyle = '#551a80'; ctx.fillRect(x + 10, y + 24, 4, 6); ctx.fillRect(x + 18, y + 24, 4, 6);
    ctx.fillStyle = '#8a2bd4'; ctx.beginPath(); ctx.arc(cx, y + 14, 12, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#b04df0'; ctx.beginPath(); ctx.arc(cx, y + 10, 8, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = '#551a80'; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(cx - 7, y + 22); ctx.lineTo(cx - 7, y + 26); ctx.stroke();
