    ctx.fillStyle = '#e74c3c'; ctx.beginPath(); ctx.arc(cx, y + 14, 10, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#ffd42a'; ctx.beginPath(); ctx.arc(cx + f * 3, y + 12, 5, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#fff08a'; ctx.beginPath(); ctx.arc(cx - 5, y + 9, 3, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#3a0a00'; ctx.beginPath(); ctx.arc(cx - 4 + f * 2, y + 16, 3, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.arc(cx + 4 + f * 2, y + 16, 3, 0, Math.PI * 2); ctx.fill();
    return;
  }
  if (e.type === 'snake') {
    // Green segmented slitherer.
    ctx.fillStyle = '#2ecc40'; ctx.beginPath(); ctx.arc(cx - 8, y + 22, 5, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.arc(cx, y + 22, 6, 0, Math.PI * 2); ctx.fill();
