    ctx.fillStyle = '#1d9c2c'; ctx.fillRect(cx + 10 + f * 4, y + 16, 8, 4); ctx.beginPath(); ctx.moveTo(cx + 16 + f * 4, y + 16); ctx.lineTo(cx + 20 + f * 4, y + 18); ctx.lineTo(cx + 16 + f * 4, y + 20); ctx.closePath(); ctx.fill();
    ctx.fillStyle = '#fff'; ctx.beginPath(); ctx.arc(cx + 6, y + 16, 3, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.arc(cx + 11, y + 16, 3, 0, Math.PI * 2); ctx.fill();
