    ctx.fillStyle = '#e8e8f0'; ctx.beginPath(); ctx.moveTo(cx - 13, y + 26); ctx.lineTo(cx - 8, y + 22); ctx.lineTo(cx - 3, y + 26); ctx.lineTo(cx + 2, y + 22); ctx.lineTo(cx + 7, y + 26); ctx.lineTo(cx + 12, y + 22); ctx.lineTo(cx + 13, y + 26); ctx.lineTo(cx + 13, y + 14); ctx.closePath(); ctx.fill();
