function drawBoss() {
  if (!boss || !boss.alive) return;
  var x = Math.round(boss.x), y = Math.round(boss.y);
  if (boss.hitTimer > 0 && (Math.floor(boss.hitTimer / 2) % 2 === 0)) return;
  // wobble effect
  boss.time = (boss.time || 0) + 0.08;
