function drawGunslingerCinematic() {
  var total = boss.introTotal || 2400;
  var p = Math.min(1, (total - introTimer) / total);
  var cx = CANVAS_W / 2, cy = CANVAS_H / 2;
  // dusty dusk sky
  var g0 = ctx.createLinearGradient(0, 0, 0, CANVAS_H);
  g0.addColorStop(0, '#2a1808'); g0.addColorStop(0.6, '#1a1005'); g0.addColorStop(1, '#0a0603');
  ctx.fillStyle = g0; ctx.fillRect(0, 0, CANVAS_W, CANVAS_H);
  // sun setting
  ctx.fillStyle = 'rgba(255,180,60,0.5)'; ctx.beginPath(); ctx.arc(cx, cy + 60, 40 - p * 10, 0, Math.PI * 2); ctx.fill();
  // town silhouette
  ctx.fillStyle = '#0d0a05';
  ctx.fillRect(20, cy + 40, 30, 60); ctx.fillRect(52, cy + 20, 8, 80); ctx.fillRect(64, cy + 40, 26, 60);
  ctx.fillRect(CANVAS_W - 90, cy + 40, 30, 60); ctx.fillRect(CANVAS_W - 56, cy + 20, 8, 80); ctx.fillRect(CANVAS_W - 44, cy + 40, 26, 60);
  ctx.fillStyle = '#0d0a05'; ctx.fillRect(0, cy + 90, CANVAS_W, CANVAS_H - cy - 90);
  // hanging sign (saloon)
  ctx.fillStyle = '#5a3a1a'; ctx.fillRect(cx - 70, cy - 10, 140, 26);
  ctx.fillStyle = '#ffd42a'; ctx.font = 'bold 14px "Courier New", monospace'; ctx.textAlign = 'center'; ctx.fillText('SALOON', cx, cy + 8); ctx.textAlign = 'left';
  // tumbleweed
  ctx.fillStyle = '#6b4a2a'; ctx.beginPath(); ctx.arc(CANVAS_W - ((p * 2) % 1) * CANVAS_W, cy + 84, 12, 0, Math.PI * 2); ctx.fill();
  // gunslinger figure
  var sway = Math.sin(p * Math.PI * 4) * 2;
  ctx.save(); ctx.translate(cx, cy + 72); ctx.scale(1.4, 1.4);
  ctx.fillStyle = '#6b4a2a'; ctx.fillRect(-11, -32, 7, 32); ctx.fillRect(4, -32, 7, 32);
  ctx.fillStyle = '#7a5433'; ctx.beginPath(); ctx.ellipse(0, -28, 15, 20, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#5a3a1a'; ctx.beginPath(); ctx.ellipse(0, -25, 12, 16, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#d9a066'; ctx.beginPath(); ctx.arc(0, -46, 8, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#2a150a'; ctx.beginPath(); ctx.ellipse(0, -52, 13, 4, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillRect(-8, -52, 16, 9);
  ctx.fillStyle = '#222'; ctx.fillRect(-5, -44, 4, 3); ctx.fillRect(2, -44, 4, 3);
  // belt + buckle
  ctx.fillStyle = '#3a2410'; ctx.fillRect(-12, -22, 24, 4);
  ctx.fillStyle = '#ffd42a'; ctx.fillRect(-2, -21, 4, 4);
  // dual guns + muzzle flashes
  var flash = (Math.floor(p * 30) % 3 === 0);
  ctx.save(); ctx.translate(16, -24); ctx.rotate(-0.35);
  ctx.fillStyle = '#555'; ctx.fillRect(0, -3, 16, 5); ctx.fillRect(12, -4, 4, 8);
  if (flash) { ctx.fillStyle = 'rgba(255,212,42,0.9)'; ctx.beginPath(); ctx.arc(20, 0, 9, 0, Math.PI * 2); ctx.fill(); ctx.fillStyle = '#fff'; ctx.beginPath(); ctx.arc(20, 0, 4, 0, Math.PI * 2); ctx.fill(); }
  ctx.restore();
  ctx.save(); ctx.translate(-16, -24); ctx.rotate(0.35);
  ctx.fillStyle = '#555'; ctx.fillRect(0, -3, 14, 5); ctx.fillRect(-3, -4, 3, 7);
  if (flash) { ctx.fillStyle = 'rgba(255,212,42,0.9)'; ctx.beginPath(); ctx.arc(-18, 0, 8, 0, Math.PI * 2); ctx.fill(); }
  ctx.restore();
  ctx.restore();
  // dust clouds at feet
  for (var du = 0; du < 4; du++) { ctx.fillStyle = 'rgba(120,90,50,' + (0.2 + Math.abs(Math.sin(p * 12 + du)) * 0.2) + ')'; ctx.beginPath(); ctx.arc(cx - 30 + du * 20, cy + 80, 8, 0, Math.PI * 2); ctx.fill(); }
  if (p > 0.85) { ctx.textAlign = 'center'; ctx.fillStyle = '#d9a066'; ctx.font = 'bold 40px "Courier New", monospace'; ctx.fillText('GUNSLINGER', cx, cy - 20); ctx.textAlign = 'left'; }
  ctx.fillStyle = '#555'; ctx.font = '11px "Courier New", monospace'; ctx.fillText('Press SPACE to skip', CANVAS_W / 2 - 60, CANVAS_H - 10);
  void sway;
}

