function updateBoss() {
  if (!boss || !boss.alive) return;
  if (boss.hitTimer > 0) boss.hitTimer--;

  // GIANT RAT: chases and releases enemies (every 1s) + mini-bosses (every 10s).
  if (boss.rat) {
    boss.dir = player.x > boss.x ? 1 : -1;
    boss.x += boss.dir * boss.speed;
    boss.releaseTimer = (boss.releaseTimer || 0) - 1;
    if (boss.releaseTimer <= 0) { boss.releaseTimer = 60; spawnRatMinion(); }
    boss.bossReleaseTimer = (boss.bossReleaseTimer || 0) - 1;
    if (boss.bossReleaseTimer <= 0) { boss.bossReleaseTimer = 600; spawnRatMiniBoss(); }
  } else if (boss.skin === 3) {
  // GLOOP GOBBLER (skin 3): gentle inhale that only pulls when level & a bit away.
    if (boss.suckTimer === undefined) boss.suckTimer = 240;
    boss.suckTimer--;
    if (boss.suckTimer < 45 && boss.suckTimer > 0) {
      var dx = (boss.x + boss.w / 2) - (player.x + player.w / 2);
      var adx = Math.abs(dx);
      var dyv = Math.abs((player.y + player.h / 2) - (boss.y + boss.h / 2));
      // Only pull when the player is roughly level and 120-520px away, so it never drags you into the boss.
      if (adx > 120 && adx < 520 && dyv < 140) player.x += (dx > 0 ? 1 : -1) * Math.min(1.2, adx * 0.003);
    }
    if (boss.suckTimer <= 0) boss.suckTimer = 240;
  } else if (boss.skin === 2 || boss.skin === 5 || boss.skin === 8) {
  // GOLEM/KNIGHT/TANK charge across the arena.
    if (boss.charging) { boss.x += boss.chargeDir * boss.speed * 2.0; boss.chargeTimer--; if (boss.chargeTimer <= 0) { boss.charging = false; boss.chargeTimer = 160; } }
    else { boss.dir = player.x > boss.x ? 1 : -1; boss.x += boss.dir * boss.speed; boss.chargeTimer--; if (boss.chargeTimer <= 0) { boss.charging = true; boss.chargeDir = boss.dir; boss.chargeTimer = 70; } }
  } else {
    boss.dir = player.x > boss.x ? 1 : -1;
    boss.x += boss.dir * boss.speed;
  }

  if (!boss.rat) {
    boss.fireTimer++;
    if (boss.fireTimer > boss.fireInterval) { boss.fireTimer = 0; bossAttack(); }
  }

  if (boss.x < 0) { boss.x = 0; boss.dir = 1; boss.chargeDir = 1; }
  if (boss.x + boss.w > levelW * TS) { boss.x = levelW * TS - boss.w; boss.dir = -1; boss.chargeDir = -1; }
  // The ghost wraith drifts up and down.
  if (boss.skin === 7) boss.y = surfaceRow() * TS - boss.h + Math.sin((boss.time || 0) * 0.1) * 26;
  else boss.y = surfaceRow() * TS - boss.h;

  // Manual (melee) attacks for some bosses: sword swings, slams, tackles, dashes.
  if (boss.meleeType) {
    if (boss.meleeActive > 0) boss.meleeActive--;
    boss.meleeTimer = (boss.meleeTimer || 0) - 1;
    if (boss.meleeTimer <= 0) { boss.meleeTimer = boss.meleeCooldown; boss.meleeActive = boss.meleeDuration; }
    if (boss.meleeActive > 0) {
