// ============================================================
//  INPUT
// ============================================================
var keys = {};
window.addEventListener('keydown', function (e) {
  ensureAudio();
  keys[e.code] = true;
  if (e.code === 'ArrowLeft' || e.code === 'ArrowRight' || e.code === 'ArrowUp' || e.code === 'ArrowDown' || e.code === 'Space') e.preventDefault();

  // Pause / resume with ESC or P.
  if (e.code === 'Escape' || e.code === 'KeyP') {
    if (state === 'playing') doPause();
    else if (state === 'pause') doResume();
  }

  // Restart: R restarts the current level (or the whole game from menus).
  if (e.code === 'KeyR') {
    if (state === 'playing' || state === 'pause') loadLevel(levelIndex);
    else startGame();
  }

  // DEV: press @ (Shift+2) to skip straight to the next level.
  if ((e.key === '@' || e.code === 'Digit2') && state === 'playing') {
    if (levelIndex < LEVELS.length - 1) loadLevel(levelIndex + 1);
    else state = 'victory';
  }

  // Menu navigation (title / pause / game over / victory).
  if (state === 'title' || state === 'pause' || state === 'gameover' || state === 'victory') {
    var items = menuItemsFor();
    if (e.code === 'ArrowUp' || e.code === 'KeyW') menuIndex = (menuIndex - 1 + items.length) % items.length;
    if (e.code === 'ArrowDown' || e.code === 'KeyS') menuIndex = (menuIndex + 1) % items.length;
    if (e.code === 'Space' || e.code === 'Enter' || e.code === 'KeyN') menuAction();
  }

  if ((state === 'levelclear' || state === 'enemyintro') && (e.code === 'Space' || e.code === 'Enter' || e.code === 'KeyN')) {
    if (state === 'enemyintro') { introTimer = 0; state = 'playing'; } // skip the WHOLE animation
    else if (levelIndex < LEVELS.length - 1) loadLevel(levelIndex + 1);
    else state = 'victory';
  }
});
window.addEventListener('keyup', function (e) { keys[e.code] = false; });

