canvas.addEventListener('click', function (e) {
  ensureAudio();
  var r = canvas.getBoundingClientRect();
  var mx = e.clientX - r.left, my = e.clientY - r.top;
  if (state === 'playing' && mx >= pauseBtn.x && mx <= pauseBtn.x + pauseBtn.w && my >= pauseBtn.y && my <= pauseBtn.y + pauseBtn.h) {
    doPause();
  }
  if (state === 'title') {
    // Settings panel controls (mute + brightness).
    if (titlePanel === 'settings') {
      if (mx >= settingsUI.muteBtn.x && mx <= settingsUI.muteBtn.x + settingsUI.muteBtn.w && my >= settingsUI.muteBtn.y && my <= settingsUI.muteBtn.y + settingsUI.muteBtn.h) {
        setMuted(!settings.muted); sfx('select'); return;
      }
      if (mx >= settingsUI.brightBar.x && mx <= settingsUI.brightBar.x + settingsUI.brightBar.w && my >= settingsUI.brightBar.y && my <= settingsUI.brightBar.y + settingsUI.brightBar.h) {
        var frac = Math.max(0, Math.min(1, (mx - settingsUI.brightBar.x) / settingsUI.brightBar.w));
        settings.brightness = settingsUI.brightMin + frac * (settingsUI.brightMax - settingsUI.brightMin);
        return;
      }
    }
    for (var i = 0; i < titleNav.length; i++) {
      var b = titleNav[i];
      if (mx >= b.x && mx <= b.x + b.w && my >= b.y && my <= b.y + b.h) {
        if (b.key === 'play') startGame();
        else if (b.key === 'settings') titlePanel = titlePanel === 'settings' ? '' : 'settings';
        else if (b.key === 'about') titlePanel = titlePanel === 'about' ? '' : 'about';
      }
    }
  }
});

