function updateFireball(e) {
  e.vy += GRAVITY; if (e.vy > MAX_FALL) e.vy = MAX_FALL;
  var ahead = e.dir > 0 ? e.x + e.w + 1 : e.x - 1;
  if (solidSide(tileAt(ahead, e.y + e.h / 2))) e.dir *= -1;
  e.x += e.dir * e.speed;
  e.onGround = false; e.y += e.vy; verticalCollide(e, false);
  if (e.onGround) { e.vy = -13; }
}

function updateGhost(e) {
  e.time += 0.05;
  var dx = player.x - e.x, dy = player.y - e.y;
  var len = Math.sqrt(dx * dx + dy * dy) || 1;
  e.x += dx / len * e.speed; e.y += dy / len * e.speed;
  e.dir = dx > 0 ? 1 : -1;
  if (e.x < 0) e.x = 0; if (e.x + e.w > levelW * TS) e.x = levelW * TS - e.w;
  if (e.y < 0) e.y = 0; if (e.y + e.h > levelH * TS) e.y = levelH * TS - e.h;
}

function updateMole(e) {
  e.popTimer++;
  e.hidden = (e.popTimer % 100) > 60;
}

function updateFlyer(e) {
  e.time += 0.05;
  e.y = e.baseY + Math.sin(e.time) * 40;
  e.dir = player.x > e.x ? 1 : -1;
  e.x += e.dir * e.speed * 0.3;
  if (e.x < 0) e.x = 0; if (e.x + e.w > levelW * TS) e.x = levelW * TS - e.w;
}

function updateGroundEnemy(e) {
  e.time = (e.time || 0) + 0.05;
  e.dir = player.x > e.x ? 1 : -1;
  e.vy += GRAVITY;
  if (e.vy > MAX_FALL) e.vy = MAX_FALL;
  if (e.type === 'hopper') { if (e.onGround) { if (e.jumpTimer <= 0) { e.vy = -12; e.onGround = false; e.jumpTimer = e.jumpPeriod; } else e.jumpTimer--; } }
  e.vx = e.dir * e.speed;
  e.x += e.vx; horizontalCollide(e);
  e.onGround = false; e.y += e.vy; verticalCollide(e, false);
  var aheadX = e.dir > 0 ? e.x + e.w + 1 : e.x - 1;
  var below = tileAt(aheadX, e.y + e.h + 2);
  var front = tileAt(e.dir > 0 ? e.x + e.w + 1 : e.x - 1, e.y + e.h / 2);
  if (!isSolid(below) || isSolid(front)) e.dir *= -1;
  if (e.x < 0) { e.x = 0; e.dir = 1; }
  if (e.x + e.w > levelW * TS) { e.x = levelW * TS - e.w; e.dir = -1; }
}

function updateChaser(e) {
  e.time += 0.06;
  var dir = player.x > e.x ? 1 : -1;
  e.x += dir * e.speed;
  e.y = e.baseY + Math.sin(e.time) * e.amp;
  if (e.x < 0) e.x = 0;
  if (e.x + e.w > levelW * TS) e.x = levelW * TS - e.w;
}

function updateCannon(e) {
  e.time = (e.time || 0) + 0.05;
  if (e.recoil > 0) e.recoil--;
  e.fireTimer++;
  if (e.fireTimer > e.fireInterval) {
    e.fireTimer = 0; e.recoil = 8;
    var speed = 2.5;
    var ang = Math.atan2((player.y + player.h / 2) - (e.y + e.h / 2), (player.x + player.w / 2) - (e.x + e.w / 2));
    projectiles.push({ x: e.x + e.w / 2 - 6, y: e.y + e.h / 2 - 6, w: 12, h: 12, vx: Math.cos(ang) * speed, vy: Math.sin(ang) * speed, done: false, from: 'cannon' });
  }
}

