function enemyDeathSfx(type) {
  var m = { patrol: 'patrol', charger: 'charger', hopper: 'hopper', chaser: 'chaser', cannon: 'cannon', fireball: 'fireball', snake: 'snake', ghost: 'ghost', mole: 'mole', flyer: 'flyer', brute: 'brute' };
  sfx(m[type] || 'stomp');

