    ctx.textAlign = 'center'; ctx.fillStyle = '#aaa'; ctx.font = 'bold 20px "Courier New", monospace'; ctx.fillText('... a knight is forged ...', cx, cy + 120); ctx.textAlign = 'left';
  } else if (ph === 3) { // helmet visor ignites
    var gl = 0.5 + 0.5 * Math.sin(t * Math.PI * 12);
    ctx.save(); ctx.translate(cx, cy + 50); ctx.scale(1.3 + t * 0.3, 1.3 + t * 0.3); drawBossBody(5, 0, 0, 1); ctx.restore();
    ctx.fillStyle = 'rgba(255,60,40,' + gl * 0.9 + ')'; ctx.fillRect(cx - 14, cy - 16, 28, 5);
