function drawTarCinematic() {
  var p = Math.min(1, (boss.introTotal - introTimer) / boss.introTotal);
  var cx = CANVAS_W / 2, cy = CANVAS_H / 2;
  var gy = cy + 130; // ground line
  ctx.fillStyle = 'rgba(6,6,8,0.97)'; ctx.fillRect(0, 0, CANVAS_W, CANVAS_H);
  ctx.fillStyle = '#0a0a0e'; ctx.fillRect(0, gy, CANVAS_W, CANVAS_H - gy);
  // 1) bubbling pit opens
  var pit = Math.min(1, p / 0.22);
  ctx.fillStyle = '#000'; fillEllipse(cx, gy, 70 * pit, 16 * pit);
  for (var i = 0; i < 10; i++) {
    var bx = cx + Math.cos(i * 1.4) * (14 * pit + 10);
    var by = gy - ((p * 40 + i * 17) % 30) * pit;
    var ba = 0.5 - Math.abs(((p * 8 + i / 10) % 1) - 0.5) * 2;
    ctx.fillStyle = 'rgba(50,46,54,' + Math.max(0, ba) + ')';
    ctx.beginPath(); ctx.arc(bx, by, 3 + i % 3, 0, Math.PI * 2); ctx.fill();
  }
  // 2) tar column rises and wobbles
  var rise = Math.max(0, (p - 0.22) / 0.5);
  var h = rise * 130;
  ctx.fillStyle = '#26262c';
  ctx.beginPath(); ctx.moveTo(cx - 30, gy); ctx.lineTo(cx - 24 - Math.sin(p * 20) * 4, gy - h); ctx.lineTo(cx + 24 + Math.sin(p * 20) * 4, gy - h); ctx.lineTo(cx + 30, gy); ctx.closePath(); ctx.fill();
  // dripping tar
  for (var d = 0; d < 6; d++) { var dx = cx - 24 + d * 9 + Math.sin(p * 10 + d) * 3; var dy = gy - h + 10 + ((p * 60 + d * 13) % 20); ctx.fillStyle = '#383840'; ctx.fillRect(dx, dy, 4, 6); }
  // 3) titan forms
  var form = Math.max(0, (p - 0.55) / 0.25);
  if (form > 0) { ctx.save(); ctx.translate(cx, gy + 4); ctx.scale(0.9 + form * 0.4, 0.9 + form * 0.4); drawBossBody(1, 0, 0, 1); ctx.restore(); }
  // 4) eyes ignite + orange shockwave
  if (p > 0.8) {
    var e = Math.min(1, (p - 0.8) / 0.15);
    ctx.fillStyle = '#ff9a2b'; ctx.beginPath(); ctx.arc(cx - 14, gy - 34, 3 + e * 5, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.arc(cx + 14, gy - 34, 3 + e * 5, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = 'rgba(255,154,43,' + e * 0.8 + ')'; ctx.lineWidth = 4;
    for (var r = 0; r < 3; r++) { ctx.beginPath(); ctx.arc(cx, gy, (30 + r * 20) * e + 20, 0, Math.PI * 2); ctx.stroke(); }
  }
  // 5) name reveal
  if (p > 0.92) {
    ctx.textAlign = 'center';
    ctx.fillStyle = '#ff9a2b'; ctx.font = 'bold 42px "Courier New", monospace'; ctx.globalAlpha = Math.min(1, (p - 0.92) * 8);
    ctx.fillText(boss.name, cx, cy - 40); ctx.globalAlpha = 1;
    ctx.fillStyle = '#fff'; ctx.font = 'bold 16px "Courier New", monospace'; ctx.fillText('THE TITAN RISES!', cx, cy + 200);
    ctx.textAlign = 'left';
  }
  ctx.fillStyle = '#555'; ctx.font = '11px "Courier New", monospace'; ctx.fillText('Press SPACE to skip', CANVAS_W / 2 - 60, CANVAS_H - 10);
}

// ---- GOO GOLEM (skin 2): stones fly in and assemble ----
function drawGolemCinematic() {
  var p = Math.min(1, (boss.introTotal - introTimer) / boss.introTotal);
  var cx = CANVAS_W / 2, cy = CANVAS_H / 2;
  ctx.fillStyle = 'rgba(8,8,10,0.97)'; ctx.fillRect(0, 0, CANVAS_W, CANVAS_H);
  // 1) floating stones converge
  for (var i = 0; i < 12; i++) {
    var a = i * 2.3 + p * 1.5;
    var dist = (1 - Math.min(1, p / 0.4)) * 340 + 20;
    var sx = cx + Math.cos(a) * dist, sy = cy + Math.sin(a) * dist * 0.7;
    var sz = 8 + (i % 4) * 5;
    ctx.save(); ctx.translate(sx, sy); ctx.rotate(a * 3);
    ctx.fillStyle = '#5a6470'; ctx.fillRect(-sz / 2, -sz / 2, sz, sz);
    ctx.fillStyle = '#6a7480'; ctx.fillRect(-sz / 2, -sz / 2, sz, sz / 3);
    ctx.restore();
  }
  // 2) golem assembles from the stones
  var form = Math.max(0, (p - 0.35) / 0.35);
  if (form > 0) { ctx.save(); ctx.translate(cx, cy + 55); ctx.scale(1.1 * form, 1.1 * form); drawBossBody(2, 0, 0, 1); ctx.restore(); }
  // 3) blue cracks glow
  if (p > 0.7) {
    var gl = Math.min(1, (p - 0.7) / 0.15);
    ctx.strokeStyle = 'rgba(43,212,255,' + gl * (0.5 + Math.abs(Math.sin(p * 20)) * 0.5) + ')';
    ctx.lineWidth = 3;
    for (var cr = 0; cr < 8; cr++) { var ca = cr * 0.8 + p * 2; ctx.beginPath(); ctx.moveTo(cx, cy + 55); ctx.lineTo(cx + Math.cos(ca) * 60 * gl, cy + 55 - 40 * gl); ctx.stroke(); }
  }
  // 4) eyes ignite red + slam
  if (p > 0.85) {
    var e2 = Math.min(1, (p - 0.85) / 0.1);
    ctx.fillStyle = '#ff3a2b'; ctx.beginPath(); ctx.arc(cx - 11, cy + 28, 3 + e2 * 5, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.arc(cx + 11, cy + 28, 3 + e2 * 5, 0, Math.PI * 2); ctx.fill();
    if (p > 0.9) { ctx.fillStyle = 'rgba(255,255,255,' + ((p - 0.9) * 10 % 1) * 0.2 + ')'; ctx.fillRect(0, 0, CANVAS_W, CANVAS_H); }
  }
  if (p > 0.92) {
    ctx.textAlign = 'center'; ctx.fillStyle = '#ffd42a'; ctx.font = 'bold 42px "Courier New", monospace'; ctx.globalAlpha = Math.min(1, (p - 0.92) * 8);
    ctx.fillText(boss.name, cx, cy - 40); ctx.globalAlpha = 1;
    ctx.fillStyle = '#fff'; ctx.font = 'bold 16px "Courier New", monospace'; ctx.fillText('THE GOLEM AWAKENS!', cx, cy + 200); ctx.textAlign = 'left';
  }
  ctx.fillStyle = '#555'; ctx.font = '11px "Courier New", monospace'; ctx.fillText('Press SPACE to skip', CANVAS_W / 2 - 60, CANVAS_H - 10);
}

// ---- GLOOP GOBBLER (skin 3): a giant maw opens and inhales ----

