  function drawWesternAmbient() {
    if (!(LEVELS[levelIndex].boss && LEVELS[levelIndex].boss.skin === 6)) return;
    var t = spikeTimer;
    // heat shimmer / rising dust
    for (var m = 0; m < 16; m++) {
      var mx = (m * 89 + Math.sin(m) * 30) % CANVAS_W;
      var my = CANVAS_H - ((t * (0.4 + (m % 4) * 0.1) + m * 90) % (CANVAS_H * 0.6));
      ctx.fillStyle = 'rgba(180,150,90,' + (0.05 + 0.08 * Math.abs(Math.sin(m + t / 30))) + ')';
      ctx.fillRect(mx, my, 2, 2);
    }
    // rolling tumbleweed (loops every ~6s)
    var tw = ((t * 1.1) % 620);
    if (t % 620 < 560) {
      var twx = ((tw / 620) * (CANVAS_W + 120)) - 60;
      var twy = CANVAS_H - 40 - Math.abs(Math.sin(t * 0.12)) * 26;
      ctx.save(); ctx.translate(twx, twy); ctx.rotate(t * 0.4);
      ctx.strokeStyle = '#6b4a2a'; ctx.lineWidth = 3;
      for (var w1 = 0; w1 < 8; w1++) { var a = w1 * Math.PI / 4; ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(Math.cos(a)*10, Math.sin(a)*10); ctx.stroke(); }
      ctx.fillStyle = 'rgba(107,74,42,0.25)'; ctx.beginPath(); ctx.arc(0,0,11,0,Math.PI*2); ctx.fill();
      ctx.restore();
    }
    // birds drifting across the sky
    for (var b = 0; b < 3; b++) {
      var bp = ((t * 0.5 + b * 320) % (CANVAS_W + 160)) - 80;
      var by = 40 + b * 26 + Math.sin(t * 0.08 + b) * 8;
      ctx.fillStyle = 'rgba(20,14,8,0.7)';
      ctx.beginPath(); ctx.moveTo(bp - 6, by); ctx.lineTo(bp, by - 3); ctx.lineTo(bp + 6, by); ctx.lineTo(bp, by + 2); ctx.closePath(); ctx.fill();
    }
    // flickering saloon window lights
    for (var wl = 0; wl < 5; wl++) {
      var wlx = ((wl * 170 + 40) % CANVAS_W);
      var wly = CANVAS_H - 20 - (wl % 2) * 40;
      var fg = 0.15 + 0.35 * Math.abs(Math.sin(t * 0.05 + wl * 2));
      ctx.fillStyle = 'rgba(255,200,80,' + fg + ')';
      ctx.fillRect(wlx, wly, 8, 8);
      ctx.fillStyle = 'rgba(255,200,80,' + fg * 0.4 + ')'; ctx.fillRect(wlx - 3, wly - 3, 14, 14);
    }
  }
