The user wants the SLUDGE KING animation to be the FIRST animation I wrote for him. 

Recall the history: When I accidentally deleted `drawSludgeCinematic` (during the laser rewrite), I then RECONSTRUCTED it. That reconstruction was the FIRST version I wrote for him — a simple one:
```
function drawSludgeCinematic() {
    var total = boss.introTotal || 2400;
    var p = Math.min(1, (total - introTimer) / total);
    var cx = CANVAS_W / 2, cy = CANVAS_H / 2;
    ctx.fillStyle = '#07160c'; ctx.fillRect(0, 0, CANVAS_W, CANVAS_H);
    ctx.fillStyle = 'rgba(0,0,0,0.45)'; ctx.fillRect(0, cy + 90, CANVAS_W, CANVAS_H - cy - 90);
    // bubbling slime pit
    for (var b = 0; b < 14; b++) {
      var bb = Math.abs(Math.sin(p * 18 + b * 1.7));
      ctx.fillStyle = 'rgba(46,204,64,' + (0.2 + bb * 0.4) + ')';
      ctx.beginPath(); ctx.arc(cx - 90 + ((p * 40 + b * 40) % 180), cy + 96 - bb * 8, 3 + bb * 6, 0, Math.PI * 2); ctx.fill();
    }
    // slime king rises out of the pit
    var rise = Math.min(1, p / 0.4);
    ctx.save(); ctx.translate(cx, cy + 92); ctx.scale(0.2 + rise * 1.6, 0.2 + rise * 1.6); drawBossBody(0, 0, 0, 1); ctx.restore();
    // dripping slime from above
    ctx.strokeStyle = 'rgba(46,204,64,0.7)'; ctx.lineWidth = 3;
    for (var d = 0; d < 4; d++) { ctx.beginPath(); ctx.moveTo(cx - 60 + d * 40, 0); ctx.lineTo(cx - 60 + d * 40 + Math.sin(p * 8 + d) * 3, (p * 60 + d * 30) % 90); ctx.stroke(); }
    // pulsing glow
    var gl = 0.5 + 0.5 * Math.sin(p * 10);
    ctx.fillStyle = 'rgba(46,204,64,' + (0.1 + gl * 0.15) + ')'; ctx.beginPath(); ctx.arc(cx, cy + 30, 120 + gl * 20, 0, Math.PI * 2); ctx.fill();
    if (p > 0.85) { ctx.textAlign = 'center'; ctx.fillStyle = '#2ecc40'; ctx.font = 'bold 40px "Courier New", monospace'; ctx.fillText('SLUDGE KING', cx, cy - 40); ctx.textAlign = 'left'; }
    ctx.fillStyle = '#555'; ctx.font = '11px "Courier New", monospace'; ctx.fillText('Press SPACE to skip', CANVAS_W / 2 - 60, CANVAS_H - 10);
  }
```

